import type { MeaningPack } from '../../types';

export const taSundaraVerses1: MeaningPack = {
  lang: 'ta',
  texts: {
    'sundarakanda-01': {
      verses: {
        '0.0': 'பின்னர் பகைவரை வாட்டும் ஹனுமான், ராவணனால் கவர்ந்து செல்லப்பட்ட சீதை இருக்கும் இடத்தைத் தேட, சாரணர்கள் சஞ்சரிக்கும் வான்வழியில் செல்ல விரும்பினான்.',
        '0.1': 'நிகரற்ற, செய்வதற்கரிய செயலைச் செய்ய விரும்பிய அந்த வானரன் தலையையும் கழுத்தையும் உயர்த்தி, காளைகளின் தலைவனைப் போல் விளங்கினான்.',
        '0.2': 'பின்பு அந்த மகாபலசாலியும் தீரனுமானவன் வைடூரிய நிறமுடைய, நீர்போல் மின்னும் புல்வெளிகளில் இன்பமாக உலாவினான்.',
        '0.3': 'அந்த அறிவாளி பறவைகளை அஞ்சச் செய்தும், மார்பால் மரங்களை முறித்தும், பல விலங்குகளைக் கொன்றும், வளர்ந்த சிங்கம் போல் திரிந்தான்.',
        '0.4': 'அந்த மலை நீலம், சிவப்பு, மஞ்சிஷ்டம், தாமரை நிறம், வெண்மை, கருமை ஆகிய இயற்கையான தூய தாதுக்களால் அலங்கரிக்கப்பட்டிருந்தது.',
        '0.5': 'விரும்பிய உருவம் எடுக்கும், தேவர்களுக்கு நிகரான யக்ஷர், கின்னரர், கந்தர்வர், நாகர்கள் தம் பரிவாரங்களுடன் அங்கு எப்போதும் வாழ்ந்தனர்.',
        '0.6': 'சிறந்த யானைகள் நிறைந்த அந்த மலையின் அடிவாரத்தில் நின்ற அந்தக் கபிசிரேஷ்டன் ஏரியில் நிற்கும் யானையைப் போல் விளங்கினான்.',
        '0.7': 'அவன் சூரியனுக்கும், மகேந்திரனுக்கும், வாயுவுக்கும், சுயம்புவான பிரம்மனுக்கும், எல்லா உயிர்களுக்கும் கைகூப்பி வணங்கிப் புறப்பட முடிவு செய்தான்.',
        '0.8': 'கிழக்கு நோக்கி நின்று தன் தந்தையான வாயுவுக்குக் கைகூப்பி, அந்தத் திறமைசாலி தெற்குத் திசைக்குச் செல்லத் தன் உடலைப் பெருக்கத் தொடங்கினான்.',
        '0.9': 'சிறந்த வானரர்கள் பார்த்திருக்க, தாவ முடிவு செய்த அவன் ராமனின் வெற்றிக்காக, பருவ நாட்களில் பொங்கும் கடல் போல் வளர்ந்தான்.',
        '0.10': 'அளவற்ற உடலுடன் கடலைக் கடக்க விரும்பிய அவன் கைகளாலும் கால்களாலும் மலையை அழுத்தினான்.',
        '0.11': 'கபியால் அழுத்தப்பட்ட அந்த மலை கணநேரம் நடுங்கி, பூத்த மரங்களின் எல்லாப் பூக்களையும் உதிர்த்தது.',
        '0.12': 'மரங்களிலிருந்து உதிர்ந்த மணம்மிக்க மலர்க்குவியலால் எங்கும் மூடப்பட்ட அந்த மலை மலர்களாலேயே ஆனது போல் தோன்றியது.',
        '0.13': 'அந்த மகா வீரனால் அழுத்தப்பட்ட மலை, மதங்கொண்ட யானை மதநீர் பெருக்குவது போல் நீரைப் பெருக்கியது.',
        '0.14': 'அந்த வலியவனால் அழுத்தப்பட்ட மகேந்திர மலை பொன், அஞ்சனம், வெள்ளி ஆகிய தாதுக்களின் ஓடைகளைப் பெருக்கியது.',
        '0.15': 'அந்த மலை மனோசிலையுடன் கூடிய பெரும் பாறைகளை உதிர்த்தது; அது நடுச்சுடரிலிருந்து புகை வரிசைகளை வெளியிடும் நெருப்பைப் போல் இருந்தது.',
        '0.16': 'கபியால் அழுத்தப்பட்ட மலையால் எங்கும் துன்புற்ற குகைகளில் வாழ்ந்த உயிரினங்கள் விகாரமான குரல்களில் கூச்சலிட்டன.',
        '0.17': 'மலை அழுத்தப்பட்டதால் எழுந்த உயிரினங்களின் அந்தப் பெரும் ஆரவாரம் பூமியையும் திசைகளையும் சோலைகளையும் நிரப்பியது.',
        '0.18': 'தெளிவான ஸ்வஸ்திக அடையாளங்கள் கொண்ட அகன்ற படங்களுடைய நாகங்கள் கொடிய நெருப்பைக் கக்கிப் பற்களால் பாறைகளைக் கடித்தன.',
        '0.19': 'சினங்கொண்ட அந்த நச்சுப் பாம்புகளால் கடிக்கப்பட்ட பெரும் பாறைகள் தீப்பற்றி எரிந்து ஆயிரம் துண்டுகளாகப் பிளந்தன.',
        '0.20': 'அந்த மலையில் வளர்ந்த மூலிகைகள் நஞ்சை முறிப்பவையாக இருந்தும் பாம்புகளின் நஞ்சைத் தணிக்க முடியவில்லை.',
        '0.21': 'இந்த மலையைப் பூதங்கள் பிளக்கின்றன என்று எண்ணி அஞ்சிய தவசிகளும் வித்யாதரர்களும் தம் பெண்களுடன் அங்கிருந்து மேலே பறந்தனர்.',
        '0.22': 'பானம் அருந்தும் இடத்தில் இருந்த பொன் மதுக்கிண்ணங்களையும், விலையுயர்ந்த பாத்திரங்களையும், பொற்கலசங்களையும் விட்டுவிட்டு,',
        '0.23': 'பலவகை நக்கி உண்ணும் பண்டங்களையும், தின்பண்டங்களையும், பலவித இறைச்சிகளையும், காளைத்தோல் கேடயங்களையும், பொற்பிடி வாள்களையும் விட்டு,',
        '0.24': 'கழுத்தில் மாலைகள் அணிந்து, மயக்கத்தில் இருந்த, சிவந்த மாலைகளும் பூச்சுகளும் கொண்ட, சிவந்த தாமரைக் கண்களுடைய அவர்கள் வானை அடைந்தனர்.',
        '0.25': 'ஆரம், சிலம்பு, தோள்வளை, கைவளை அணிந்த பெண்கள் வியப்புடனும் புன்னகையுடனும் தம் காதலருடன் வானில் நின்றனர்.',
        '0.26': 'தம் மகா வித்தையைக் காட்டியபடி வித்யாதரர்களும் மகரிஷிகளும் ஒன்றாக வானில் நின்று மலையை நோக்கினர்.',
        '0.27': 'அப்போது தெளிந்த வானில் நின்ற தூய உள்ளம் கொண்ட ரிஷிகள், சாரணர்கள், சித்தர்கள் ஆகியோரின் சொற்களை அவர்கள் கேட்டனர்:',
        '0.28': '"மலை போன்ற, பெரும் வேகம் கொண்ட இந்த வாயுபுத்திரன் ஹனுமான் வருணனின் இருப்பிடமான கடலைக் கடக்க விரும்புகிறான்.',
        '0.29': 'ராமனுக்காகவும் வானரர்களுக்காகவும் அரிய செயலைச் செய்ய விரும்பி, அடைவதற்கரிய கடலின் மறுகரையை அடைய விரும்புகிறான்."',
        '0.30': 'அந்தத் தவசிகளின் இச்சொற்களைக் கேட்டு வித்யாதரர்கள் மலைமேல் இருந்த அளவிட முடியாத அந்த வானர சிரேஷ்டனைக் கண்டனர்.',
        '0.31': 'மலை போன்ற அவன் மயிர்களைச் சிலிர்த்தான், உடலை அசைத்தான், பெரும் மேகம் போல் பெருமுழக்கம் செய்தான்.',
        '0.32': 'தாவத் தயாரான அவன் வரிசையாக உருண்டு, மயிர் நிறைந்த தன் வாலைப் பறவையரசன் கருடன் பாம்பை வீசுவது போல் வீசினான்.',
        '0.33': 'அதிவேகனான அவனுடைய முதுகுக்குப் பின் சுருண்ட வால், கருடனால் தூக்கிச் செல்லப்படும் பெரும் பாம்பு போல் தோன்றியது.',
        '0.34': 'அந்தக் கபி பெரும் உலக்கைத் தடிகளைப் போன்ற கைகளை இறுக்கினான், இடுப்பைச் சுருக்கினான், கால்களை மடக்கினான்.',
        '0.35': 'கைகளையும் கழுத்தையும் சுருக்கிக் கொண்டு, அந்த ஒளிமிக்க வீரன் தன்னுள் தேஜஸ், சத்துவம், வீரியம் ஆகியவற்றை நிரப்பிக் கொண்டான்.',
        '0.36': 'தொலைவு வரை தன் வழியைப் பார்த்து, கண்களை மேலே வானில் பதித்து, மூச்சை நெஞ்சில் அடக்கினான்.',
        '0.37': 'கால்களை உறுதியாக ஊன்றி, காதுகளை மடக்கி, தாவத் தயாரான அந்த மகாபலசாலி கபிசிரேஷ்டன் ஹனுமான்,',
        '0.38': 'அந்த வானர சிரேஷ்டன் வானரர்களிடம் இவ்வாறு கூறினான்: "ராகவன் எய்த அம்பு காற்றின் வேகத்தில் செல்வது போல்,',
        '0.39': 'அவ்வாறே நான் ராவணன் ஆளும் இலங்கைக்குச் செல்வேன். இலங்கையில் ஜனகனின் மகளைக் காணாவிட்டால்,',
        '0.40': 'இதே வேகத்துடன் தேவலோகத்துக்குச் செல்வேன்; உழைத்தும் சொர்க்கத்தில் சீதையைக் காணாவிட்டால்,',
        '0.41': 'அரக்கர் அரசன் ராவணனைக் கட்டிக் கொண்டு வருவேன். எப்படியாயினும் காரியத்தை முடித்துச் சீதையுடன் திரும்புவேன்,',
        '0.42': 'அல்லது ராவணனோடு இலங்கையையே பெயர்த்துக் கொண்டு வருவேன்." இவ்வாறு கூறி வானரோத்தமனான ஹனுமான்,',
        '0.43': 'வேகமுடைய அவன் சிறிதும் தயங்காமல் விரைந்து மேலே தாவினான்; அந்தக் கபிசிரேஷ்டன் தன்னைக் கருடனாகவே எண்ணினான்.',
        '0.44': 'அவன் வேகமாக எழுந்தபோது அந்த வேகத்தால் இழுக்கப்பட்ட மலைமரங்கள் கிளைகளைச் சுருக்கிக் கொண்டு சுற்றிலும் மேலே எழுந்தன.',
        '0.45': 'மதம் கொண்ட ஆள்காட்டிப் பறவைகள் நிறைந்த பூத்த மரங்களைத் தொடைகளின் வேகத்தால் இழுத்துக் கொண்டு அவன் தெளிந்த வானில் சென்றான்.',
        '0.46': 'தொடைகளின் வேகத்தால் எழுந்த மரங்கள், நீண்ட பயணம் புறப்பட்ட உறவினனை உறவினர் பின்தொடர்வது போல், சிறிது நேரம் கபியைப் பின்தொடர்ந்தன.',
        '0.47': 'தொடைகளின் வேகத்தால் பெயர்க்கப்பட்ட சால மரங்களும் பிற சிறந்த மரங்களும், படைவீரர் அரசனைப் பின்தொடர்வது போல் ஹனுமானைப் பின்தொடர்ந்தன.',
        '0.48': 'பூத்த நுனிகள் கொண்ட பல மரங்களுடன் கூடிய மலைபோன்ற ஹனுமான் அற்புதக் காட்சியாக விளங்கினான்.',
        '0.49': 'கனமான மரங்கள் உப்புக் கடலில் மூழ்கின — மகேந்திரனுக்கு அஞ்சி மலைகள் வருணனின் கடலில் மூழ்கியது போல்.',
        '0.50': 'பலவித மலர்கள், தளிர்கள், மொட்டுகளால் மூடப்பட்ட மேகம் போன்ற கபி மின்மினிகளால் ஒளிரும் மலை போல் விளங்கினான்.',
        '0.51': 'அவன் வேகத்திலிருந்து விடுபட்ட அந்த மரங்கள் மலர்களை உதிர்த்து, வழியனுப்பித் திரும்பும் நண்பர்களைப் போல் நீரில் விழுந்தன.',
        '0.52': 'கபியின் காற்றால் பறந்த இலேசான பல வண்ண மலர்கள் கடலில் விழுந்தன; அந்தப் பெருங்கடல் விண்மீன்கள் நிறைந்த வானம் போல் ஒளிர்ந்தது.',
        '0.53': 'பல நிற மணமலர்க் குவியலால் மூடப்பட்ட வானரன் மின்னல்களால் அலங்கரிக்கப்பட்ட எழும் மேகம் போல் தோன்றினான்.',
        '0.54': 'அவன் வேகத்தால் பறந்த மலர்களால் மூடப்பட்ட நீர், எழுந்த அழகிய விண்மீன்கள் கொண்ட வானம் போல் தோன்றியது.',
        '0.55': 'வானில் நீட்டிய அவன் கைகள் மலைமுடியிலிருந்து வெளிப்பட்ட ஐந்து தலை நாகங்கள் இரண்டைப் போல் தோன்றின.',
        '0.56': 'அந்த மகாகபி அலைகள் நிறைந்த பெருங்கடலைக் குடிப்பவன் போலவும், வானத்தைக் குடிக்கத் தாகம் கொண்டவன் போலவும் தோன்றினான்.',
        '0.57': 'காற்றின் வழியில் சென்ற அவனுடைய மின்னல் போன்ற கண்கள் மலைமேல் எரியும் இரு தீக்களைப் போல் ஒளிர்ந்தன.',
        '0.58': 'பழுப்புக் கண்ணர்களில் முதன்மையான அவனுடைய பழுப்பு நிறப் பெரிய வட்டக் கண்கள் சந்திரனும் சூரியனும் போல் ஒளிர்ந்தன.',
        '0.59': 'செம்பு நிற மூக்கால் சிவந்த அவன் முகம் அந்திவானம் தொட்ட சூரிய வட்டம் போல் ஒளிர்ந்தது.',
        '0.60': 'வானில் பறந்த வாயுபுத்திரனின் உயர்த்திய வால் உயரே ஏற்றிய இந்திரக் கொடி போல் விளங்கியது.',
        '0.61': 'வாலைச் சக்கரம் போல் சுருட்டிய, வெண்பற்களுடைய மகாப்ராக்ஞனான வாயுபுத்திரன் ஒளிவட்டம் கொண்ட சூரியன் போல் விளங்கினான்.',
        '0.62': 'மிகச் சிவந்த பின்பகுதியால் அந்த மகாகபி காவிக்கல் வெடித்துத் தெரியும் மலை போல் விளங்கினான்.',
        '0.63': 'கடல்மேல் பறந்த அந்த வானரசிம்மனின் அக்குள்களில் புகுந்த காற்று மேகம் போல் முழங்கியது.',
        '0.64': 'வடதிசையிலிருந்து புறப்பட்டு வாலுடன் வானில் விழும் எரிநட்சத்திரம் போல் அந்தக் கபிசிரேஷ்டன் தோன்றினான்.',
        '0.65': 'செல்லும் சூரியன் போல் நீண்டு விரிந்த அந்தக் கபி, கச்சையால் கட்டப்படும் பெரிய யானை போல் விளங்கினான்.',
        '0.66': 'மேலே உடலும் கீழே கடலில் ஆழ்ந்த நிழலுமாக அந்தக் கபி காற்றால் செலுத்தப்படும் கப்பல் போல் தோன்றினான்.',
        '0.67': 'அந்த மகாகபி கடலின் எந்தெந்தப் பகுதியின் மேல் சென்றானோ அப்பகுதி அவன் உடல் வேகத்தால் வெறிகொண்டது போல் தோன்றியது.',
        '0.68': 'மலைபோல் உயர்ந்த கடல் அலைகளை மார்பால் மோதியபடி அந்த மகாவேகனான மகாகபி முன்னே சென்றான்.',
        '0.69': 'கபியிடமிருந்து எழுந்த வலிய காற்றும் மேகக் காற்றும் சேர்ந்து, அச்சமூட்டும் முழக்கமிடும் கடலைக் கடுமையாக அசைத்தன.',
        '0.70': 'உப்புக் கடலின் பெரும் அலைகளை இழுத்தபடி அந்தக் கபிசார்தூலன் வானையும் மண்ணையும் சிதறடிப்பவன் போல் பறந்தான்.',
        '0.71': 'பெருங்கடலில் மேரு மந்தரம் போல் எழுந்த அலைகளை எண்ணுபவன் போல் அந்த வேகன் கடந்து சென்றான்.',
        '0.72': 'அவன் வேகத்தால் எழுந்து மேகங்களை அடைந்த நீர் வானில் பரவிய கூதிர்கால மேகம் போல் ஒளிர்ந்தது.',
        '0.73': 'திமிங்கிலங்கள், முதலைகள், மீன்கள், ஆமைகள் ஆடை இழுக்கப்பட்ட உடல்கள் போல் வெளிப்பட்டுத் தெரிந்தன.',
        '0.74': 'வானில் செல்லும் அந்தக் கபிசார்தூலனைக் கண்டு கடல் நாகங்கள் அவனைக் கருடன் என்று எண்ணின.',
        '0.75': 'பத்து யோஜனை அகலமும் முப்பது யோஜனை நீளமும் கொண்ட அந்த வானரசிம்மனின் நிழல் வேகத்தில் மேலும் அழகாயிற்று.',
        '0.76': 'வாயுபுத்திரனைப் பின்தொடர்ந்து உப்புக் கடலில் விழுந்த அந்த நிழல் வெண்மையான அடர்ந்த மேக வரிசை போல் விளங்கியது.',
        '0.77': 'பேரொளியும் பெரும் உடலும் கொண்ட அந்த மகாகபி ஆதாரமற்ற வான்வழியில் சிறகுள்ள மலை போல் விளங்கினான்.',
        '0.78': 'அந்த வலிய கபிசிரேஷ்டன் வேகமாகச் சென்ற வழியில் கடல் திடீரென்று தொட்டி போல் குழிந்தது போல் தோன்றியது.',
        '0.79': 'பறவைகளின் வழியில் பறவையரசன் போல் சென்ற ஹனுமான் காற்றைப் போல் மேகக் கூட்டங்களை இழுத்துச் சென்றான்.',
        '0.80': 'கபியால் இழுக்கப்பட்ட வெண்மை, செம்மை, நீலம், மஞ்சிஷ்ட நிறப் பெருமேகங்கள் ஒளிர்ந்தன.',
        '0.81': 'மேகக் கூட்டங்களுக்குள் புகுந்து மீண்டும் மீண்டும் வெளிவந்து அவன் சந்திரன் போல் மறைந்தும் தோன்றியும் காணப்பட்டான்.',
        '0.82': 'விரைந்து பறக்கும் அந்தக் கபியைக் கண்டு தேவர்களும் கந்தர்வர்களும் சாரணர்களும் அவன்மேல் மலர் மாரி பொழிந்தனர்.',
        '0.83': 'பறந்து சென்ற அந்த வானர அரசனைச் சூரியன் சுடவில்லை; ராம காரியம் நிறைவேற வாயு அவனுக்குப் பணிவிடை செய்தான்.',
        '0.84': 'வானில் பறந்த அவனை ரிஷிகள் துதித்தனர்; தேவ கந்தர்வர்கள் அந்த வனவாசியைப் புகழ்ந்து பாடினர்.',
        '0.85': 'களைப்பே இல்லாத அந்தக் கபிசிரேஷ்டனைக் கண்டு நாகர்களும் யக்ஷர்களும் பலவித அரக்கர்களும் அனைவரும் அவனைப் புகழ்ந்தனர்.',
        '0.86': 'கபிசார்தூலனான ஹனுமான் பறந்து கொண்டிருந்தபோது, இக்ஷ்வாகு குலத்தைப் போற்ற விரும்பிய சமுத்திரராஜன் சிந்தித்தான்:',
        '0.87': '"வானர இந்திரனான ஹனுமானுக்கு நான் உதவாவிட்டால் பேசுவோர் அனைவரின் பழிக்கும் ஆளாவேன்.',
        '0.88': 'இக்ஷ்வாகுத் தலைவனான சகரனால் நான் பெருக்கப்பட்டேன்; இவன் இக்ஷ்வாகுக்களின் துணைவன், ஆகவே இவன் களைப்படையக் கூடாது.',
        '0.89': 'கபி ஓய்வெடுக்கும்படி நான் ஏற்பாடு செய்ய வேண்டும்; என்மேல் ஓய்வெடுத்து மீதமுள்ள தொலைவை அவன் இன்பமாகக் கடப்பான்."',
        '0.90': 'இந்த நல்ல முடிவை எடுத்துச் சமுத்திரன் தன் நீரில் மறைந்திருந்த பொன் நடுவுடைய சிறந்த மலையான மைனாகனிடம் கூறினான்.',
        '0.91': '"பாதாளத்தில் வாழும் அசுரக் கூட்டங்களுக்குத் தடையாக மகாத்மாவான தேவராஜன் உன்னை இங்கே நிறுத்தியுள்ளான்.',
        '0.92': 'வலிமை அறியப்பட்ட, மீண்டும் மேலெழ விரும்பும் இந்த அசுரர்களுக்காக அளவற்ற பாதாளத்தின் வாயிலை மூடி நீ நிற்கிறாய்.',
        '0.93': 'மலையே, குறுக்காகவும் மேலும் கீழும் வளரும் ஆற்றல் உனக்கு உண்டு; ஆகவே உன்னைத் தூண்டுகிறேன் — எழுவாய், மலைகளில் சிறந்தவனே!',
        '0.94': 'ராம காரியத்தை நாடிய, அஞ்சத்தக்க செயல்களைச் செய்யும் அந்த வீரக் கபிசார்தூலன் ஹனுமான் வானில் தாவி உன்மேல் வருகிறான்.',
        '0.95': 'இக்ஷ்வாகு குலத்திற்குப் பணிபுரியும் இவனுக்கு நான் உதவ வேண்டும். இக்ஷ்வாகுக்கள் எனக்குப் பூஜ்யர்கள், உனக்கோ மிகவும் பூஜ்யர்கள்.',
        '0.96': 'எங்களுக்கு உதவு; எங்கள் கடமை தவறக் கூடாது. செய்ய வேண்டியதைச் செய்யாவிட்டால் நல்லோரின் சினத்தைத் தூண்டும்.',
        '0.97': 'நீரிலிருந்து மேலே எழு; இந்தக் கபி உன்மேல் தங்கட்டும். தாவுவோரில் சிறந்த இவன் நம் விருந்தினன், போற்றத்தக்கவன்.',
        '0.98': 'பொன்மயமான பெரும் நடுவுடையவனே, தேவ கந்தர்வர்களால் போற்றப்படுபவனே! உன்மேல் ஓய்வெடுத்து ஹனுமான் மீதி வழியைக் கடப்பான்.',
        '0.99': 'காகுத்ஸ்தனின் (ராமனின்) கருணையையும், மைதிலியின் பிரிவையும், வானர அரசனின் உழைப்பையும் கருதி நீ எழ வேண்டும்."',
        '0.100': 'உப்புக் கடலின் சொல்லைக் கேட்டு, பெரும் மரங்களாலும் கொடிகளாலும் சூழப்பட்ட பொன்கருவுடைய மைனாகன் விரைவில் நீரிலிருந்து மேலெழுந்தான்.',
        '0.101': 'கடல் நீரைப் பிளந்து, மேகத்தைப் பிளந்து எழும் ஒளிமிக்க சூரியன் போல் அவன் மிக உயர எழுந்தான்.',
        '0.102': 'கணப்பொழுதில் நீரால் மூடப்பட்டிருந்த அந்த மாமலை கடலின் கட்டளைப்படி தன் சிகரங்களைக் காட்டியது.',
        '0.103': 'கின்னரர்களும் பெரும் நாகங்களும் வாழ்ந்த, உதயசூரியன் போல் ஒளிர்ந்த அதன் பொற்சிகரங்கள் வானைக் கீறுவது போல் இருந்தன.',
        '0.104': 'எழுந்த அந்த மலையின் பொற்சிகரங்களால் வாள் போல் கருத்திருந்த வானம் பொன்னொளி பெற்றது.',
        '0.105': 'ஒளிவீசும் பொற்சிகரங்களால் அந்தச் சிறந்த மலை நூறு சூரியர்கள் போல் தோன்றியது.',
        '0.106': 'உப்புக் கடலின் நடுவே தன் முன் திடீரென எழுந்து நின்ற அதைக் கண்டு ஹனுமான் "இது ஒரு தடை" என்று முடிவு செய்தான்.',
        '0.107': 'அந்த மகாவேகனான மகாகபி மிக உயர்ந்த அந்த மலையைக் காற்று மேகத்தைத் தள்ளுவது போல் மார்பால் தள்ளினான்.',
        '0.108': 'கபியால் இவ்வாறு தள்ளப்பட்ட அந்த மலைச்சிறந்தோன் அவன் வேகத்தை உணர்ந்து மகிழ்ந்து முழங்கினான்.',
        '0.109': 'வானில் இருந்த அந்த வீரனருகே வானிலேயே நின்று, மகிழ்ந்த உள்ளத்துடன் அந்த மலை கபியிடம் கூறியது.',
        '0.110': 'மனித உருவம் எடுத்துத் தன் சிகரத்தில் நின்று கூறினான்: "வானரோத்தமனே, நீ இந்த அரிய செயலைச் செய்துள்ளாய்.',
        '0.111': 'என் சிகரங்களில் இறங்கி இன்பமாக ஓய்வெடுத்துப் பிறகு செல். ராகவனின் குலத்தில் பிறந்தோரால் கடல் பெருக்கப்பட்டது.',
        '0.112': 'ஆகவே ராமனின் நலனில் ஈடுபட்ட உன்னைக் கடல் பதிலுக்குப் போற்றுகிறது; செய்த நன்மைக்குக் கைம்மாறு செய்வதே நிலையான தர்மம்.',
        '0.113': 'அந்த நன்றியைச் செலுத்த விரும்பும் அவன் உன்னிடமிருந்து மதிப்புப் பெறத் தகுந்தவன்; உனக்காகப் பெருமதிப்புடன் அவன் என்னைத் தூண்டினான்.',
        '0.114': '\'இந்தக் கபி நூறு யோஜனை கடக்க வானில் தாவியுள்ளான்; உன் சரிவுகளில் ஓய்வெடுத்து மீதி வழியைக் கடக்கட்டும்\' என்று அவன் கூறினான்.',
        '0.115': 'கபிசார்தூலனே, நில்; என்மேல் ஓய்வெடுத்துச் செல். இங்கே மணமும் சுவையும் உள்ள கிழங்குகள், வேர்கள், பழங்கள் ஏராளம் உள்ளன.',
        '0.116': 'ஹரிசிரேஷ்டனே, அவற்றைச் சுவைத்து ஓய்வெடுத்துப் பின் செல்வாய். கபிமுக்கியனே, மூவுலகிலும் புகழ்பெற்ற, மேன்மையான ஒரு உறவு எங்களுக்கும் உன்னோடு உண்டு.',
        '0.117': 'வாயுமைந்தனே, விரைந்து தாவும் வானரர்கள் அனைவரிலும் உன்னையே முதன்மையானவனாகக் கருதுகிறேன், கபிகுஞ்சரனே.',
        '0.118': 'தர்மத்தை அறிய விரும்பும் அறிவாளிக்குச் சாதாரண விருந்தினரும் போற்றத்தக்கவர்; உன்னைப் போன்றவரைப் பற்றிச் சொல்ல வேண்டுமா!',
        '0.119': 'நீ தேவர்களில் சிறந்த மகாத்மாவான வாயுவின் மைந்தன்; வேகத்தில் அவனுக்கே நிகரானவன், கபிகுஞ்சரனே.',
        '0.120': 'தர்மம் அறிந்த உன்னைப் போற்றினால் வாயுவே போற்றப்படுகிறான்; ஆகவே நீ எனக்குப் பூஜிக்கத் தக்கவன். அதற்கான காரணத்தையும் கேள்.',
        '0.121': 'அன்பனே, முன்பு கிருதயுகத்தில் மலைகளுக்குச் சிறகுகள் இருந்தன; அவை கருடனைப் போல் விரைந்து எல்லாத் திசைகளுக்கும் பறந்தன.',
        '0.122': 'அவை பறந்து திரிந்தபோது தேவர் கூட்டங்களும் ரிஷிகளும் உயிர்களும் அவை தம்மேல் விழுமோ என்று அஞ்சினர்.',
        '0.123': 'அப்போது சினந்த ஆயிரம் கண்ணனான சதக்ரது (இந்திரன்) வஜ்ராயுதத்தால் நூறாயிரக்கணக்கான மலைகளின் சிறகுகளை வெட்டினான்.',
        '0.124': 'சினந்த தேவராஜன் வஜ்ரத்தை உயர்த்தி என்னிடமும் வந்தான்; அப்போது மகாத்மாவான வாயு என்னைத் திடீரென்று தூக்கி எறிந்தான்.',
        '0.125': 'கபிசிரேஷ்டனே, இந்த உப்புக் கடலில் எறியப்பட்ட நான் உன் தந்தையால் காக்கப்பட்டுச் சிறகுகளுடன் முழுமையாக இருந்தேன்.',
        '0.126': 'ஆகவே உன்னை மதிக்கிறேன்; மாருதியே, நீ எனக்கு மதிப்புக்குரியவன். கபிமுக்கியனே, உன்னுடன் எனக்குள்ள இந்த உறவு மிக மேன்மையானது.',
        '0.127': 'இத்தகைய வாய்ப்பு வந்துள்ளபோது, பேரறிவாளனே, நீ மகிழ்ந்த மனத்துடன் கடலுக்கும் எனக்கும் மகிழ்ச்சி அளிக்க வேண்டும்.',
        '0.128': 'ஹரிசத்தமனே, களைப்பை நீக்கி என் உபசாரத்தையும் அன்பையும் ஏற்றுக்கொள்; உன்னைக் கண்டு மகிழ்கிறேன்."',
        '0.129': 'இவ்வாறு சொல்லப்பட்ட கபிசிரேஷ்டன் அந்தச் சிறந்த மலையிடம் கூறினான்: "நான் மகிழ்ந்தேன்; உபசாரம் நடந்ததாகவே கொள். மனவருத்தம் வேண்டாம்.',
        '0.130': 'என் காரியத்திற்கான நேரம் விரைகிறது, பகலும் கடந்து போகிறது; இடையில் எங்கும் நிற்கமாட்டேன் என்று சபதம் செய்துள்ளேன்."',
        '0.131': 'இவ்வாறு கூறி அந்தக் கபிசிரேஷ்டன் கையால் மலையைத் தொட்டு, புன்னகைப்பவன் போல் வானில் புகுந்து சென்றான்.',
        '0.132': 'மலையும் கடலும் அவனைப் பெருமதிப்புடன் நோக்கின; தகுந்த ஆசிகளால் அவனைப் போற்றி வாழ்த்தின.',
        '0.133': 'பின்னர் மிக உயரச் சென்று, மலையையும் பெருங்கடலையும் விட்டு, தந்தையின் வழியான வான்வழியை அடைந்து தெளிந்த வானில் சென்றான்.',
        '0.134': 'மேலும் உயர எழுந்து அந்த மலையைப் பார்த்தபடி வாயுபுத்திரனான கபிசிரேஷ்டன் ஆதாரமின்றிச் சென்றான்.',
        '0.135': 'ஹனுமானின் இந்த இரண்டாவது மிக அரிய செயலைக் கண்டு தேவர்கள், சித்தர்கள், மகரிஷிகள் அனைவரும் அவனைப் புகழ்ந்தனர்.',
        '0.136': 'அங்கிருந்த தேவர்களும் ஆயிரம் கண்ணனான வாசவனும் (இந்திரனும்) பொன்மய சுநாபனின் (மைனாகனின்) அச்செயலால் மகிழ்ந்தனர்.',
        '0.137': 'அறிவாளியான சசிபதி தானே மகிழ்ச்சியுடன் தழுதழுத்த குரலில் மலைச்சிறந்தோனான சுநாபனிடம் கூறினான்:',
        '0.138': '"ஹிரண்யநாபனே, மலைகளின் அரசே, உன்னிடம் மிகவும் மகிழ்ந்தேன். உனக்கு அபயம் அளிக்கிறேன்; சாந்தனே, விரும்பியபடி செல்.',
        '0.139': 'அச்சம் நிறைந்த இடத்திலும் அஞ்சாமல் நூறு யோஜனை கடக்கும் வீரன் ஹனுமானுக்கு நீ பெரும் உதவி செய்துள்ளாய்.',
        '0.140': 'இந்தக் கபி தசரத மைந்தன் ராமனின் நலனுக்காகவே செல்கிறான்; இயன்றவரை அவனைப் போற்றிய நீ என்னை உறுதியாக மகிழ்வித்தாய்."',
        '0.141': 'தேவர்களின் தலைவனான சதக்ரது மகிழ்ந்ததைக் கண்டு அந்த மலைச்சிறந்தோன் பேரானந்தம் அடைந்தான்.',
        '0.142': 'வரம் பெற்ற அந்த மலை அங்கேயே நின்றது; ஹனுமான் கணப்பொழுதில் அக்கடல் பகுதியைக் கடந்தான்.',
        '0.143': 'அப்போது தேவர்கள் கந்தர்வர், சித்தர், மகரிஷிகளுடன் சூரியனைப் போல் ஒளிரும் நாகமாதா சுரசையிடம் கூறினர்:',
        '0.144': '"ஹனுமான் என்ற பெயருடைய இந்த ஒளிமிக்க வாயுபுத்திரன் கடல்மேல் பறக்கிறான்; கணநேரம் அவனுக்குத் தடை ஏற்படுத்து.',
        '0.145': 'மலைபோன்ற கொடிய அரக்கி உருவம் எடுத்து, அச்சமூட்டும் கோரைப்பற்களும் பழுப்புக் கண்களும் வானைத் தொடும் வாயும் கொள்.',
        '0.146': 'அவன் வலிமையையும் வீரத்தையும் மேலும் அறிய விரும்புகிறோம் — அவன் உபாயத்தால் உன்னை வெல்வானா, அல்லது மனம் தளர்வானா."',
        '0.147': 'தேவர்களால் இவ்வாறு கூறப்பட்டுப் போற்றப்பட்ட சுரசா தேவி கடலின் நடுவே அரக்கி உடலை எடுத்து,',
        '0.148': 'விகாரமான, அருவருப்பான, அனைவருக்கும் அச்சமூட்டும் உருவத்துடன் பறந்து வந்த ஹனுமானைத் தடுத்து இவ்வாறு கூறினாள்:',
        '0.149': '"வானர சிரேஷ்டனே, தேவர்கள் உன்னை எனக்கு உணவாக விதித்துள்ளனர்; நான் உன்னை உண்பேன். என் இந்த வாயில் நுழை."',
        '0.150': '"இது முன்பு பிரம்மன் எனக்களித்த வரம்" என்று விரைவாகக் கூறி, அவள் அகன்ற வாயைத் திறந்து மாருதியின் முன் நின்றாள்.',
        '0.151': 'சுரசை இவ்வாறு கூறியதும் ஹனுமான் மலர்ந்த முகத்துடன் கூறினான்: "தசரத மைந்தன் ராமன் தன் தம்பி லக்ஷ்மணனுடனும் மனைவி வைதேஹியுடனும் தண்டகவனத்தில் புகுந்தான்.',
        '0.152': 'அவன் வேறு காரியத்தில் ஈடுபட்டிருந்தபோது, அரக்கர்களுடன் பகை ஏற்பட்டிருந்ததால், அவனுடைய புகழ்மிக்க மனைவி சீதையை ராவணன் கவர்ந்து சென்றான்.',
        '0.153': 'ராமனின் கட்டளைப்படி நான் தூதனாக அவளிடம் செல்கிறேன். அவன் நாட்டில் வாழும் நீ ராமனுக்கு உதவ வேண்டும்.',
        '0.154': 'அல்லது மைதிலியையும், களைப்பின்றிச் செயல்படும் ராமனையும் கண்டபின் உன் வாய்க்குள் வருவேன் — இது சத்தியம், உனக்கு வாக்களிக்கிறேன்."',
        '0.155': 'ஹனுமான் இவ்வாறு கூறியதும் விரும்பிய உருவெடுக்கும் சுரசை "யாரும் என்னைக் கடந்து செல்ல முடியாது; இது என் வரம்" என்றாள்.',
        '0.156': 'அவன் முன்னே செல்வதைக் கண்டு, ஹனுமானின் வலிமையை அறிய விரும்பிய நாகமாதா சுரசை கூறினாள்:',
        '0.157': '"வானரோத்தமனே, இன்று என் வாயில் நுழைந்த பின்பே நீ செல்ல வேண்டும்; இது முன்பு பிரம்மன் எனக்களித்த வரம்."',
        '0.158': 'இவ்வாறு விரைவாகக் கூறி அவள் அகன்ற வாயைத் திறந்து மாருதியின் முன் நின்றாள். சுரசையின் இச்சொல்லால் வானர சிரேஷ்டன் சினந்து,',
        '0.159': '"அப்படியானால் என்னைத் தாங்கும் அளவு வாயைப் பெரிதாக்கு" என்றான். பத்து யோஜனை விரிந்திருந்த சுரசையிடம் சினத்துடன் இவ்வாறு கூறி,',
        '0.160': 'அப்போது ஹனுமான் பத்து யோஜனை அகலமானான். மேகம் போன்ற பத்து யோஜனை அளவுள்ள அவனைக் கண்டு சுரசை தன் வாயை இருபது யோஜனை அகலமாக்கினாள்.',
        '0.161': 'அப்போது ஹனுமான் சினத்துடன் முப்பது யோஜனை வளர்ந்தான்; சுரசை தன் வாயை நாற்பது யோஜனை உயரமாக்கினாள்.',
        '0.162': 'வீரன் ஹனுமான் ஐம்பது யோஜனை உயரமானான்; சுரசை வாயை அறுபது யோஜனை உயரமாக்கினாள்.',
        '0.163': 'உடனே வீரன் ஹனுமான் எழுபது யோஜனை உயரமானான்; சுரசை வாயை எண்பது யோஜனை உயரமாக்கினாள்.',
        '0.164': 'நெருப்புப் போல் ஒளிரும் ஹனுமான் தொண்ணூறு யோஜனை உயரமானான்; சுரசை வாயை நூறு யோஜனை அகலமாக்கினாள்.',
        '0.165': 'நீண்ட நாக்குடைய, நரகம் போல் பயங்கரமான சுரசையின் அந்தத் திறந்த வாயைக் கண்டு அறிவாளியான வாயுபுத்திரன்,',
        '0.166': 'மேகம் போல் தன் உடலைச் சுருக்கிக் கொண்டான்; அக்கணமே ஹனுமான் கட்டைவிரல் அளவினன் ஆனான்.',
        '0.167': 'அவள் வாயில் நுழைந்து மீண்டும் வெளிவந்து அந்த மகாபலசாலி வானில் நின்று இவ்வாறு கூறினான்:',
        '0.168': '"தாக்ஷாயணியே, உன் வாயில் நுழைந்துவிட்டேன்; உனக்கு வணக்கம். வைதேஹி இருக்குமிடம் செல்வேன்; உன் வரமும் உண்மையாயிற்று."',
        '0.169': 'ராகுவின் வாயிலிருந்து விடுபட்ட சந்திரன் போல் தன் வாயிலிருந்து வெளிப்பட்ட அந்தக் கபியைக் கண்டு சுரசா தேவி தன் சொந்த உருவில் கூறினாள்:',
        '0.170': '"ஹரிசிரேஷ்டனே, சாந்தனே, காரிய சித்திக்காக இன்பமாகச் செல்; வைதேஹியை மகாத்மாவான ராகவனுடன் சேர்த்து வை."',
        '0.171': 'ஹனுமானின் இந்த மூன்றாவது மிக அரிய செயலைக் கண்டு எல்லா உயிர்களும் "நன்று, நன்று" என்று கபியைப் புகழ்ந்தன.',
        '0.172': 'வெல்ல முடியாத வருணனின் இருப்பிடமான கடலை அடைந்து, கருடன் போல் விரைந்து வானில் புகுந்து அவன் சென்றான்,',
        '0.173': 'மழைத் தாரைகளால் நிறைந்த, பறவைகள் திரியும், இசை ஆசான்கள் (கந்தர்வர்) உலவும், ஐராவதம் செல்லும் வானில்,',
        '0.174': 'சிங்கம், யானை, புலி, பறவை, பாம்பு ஆகியவற்றை வாகனமாகக் கொண்ட, பறக்கும் தூய விமானங்களால் அலங்கரிக்கப்பட்ட,',
        '0.175': 'வஜ்ரம் போன்ற தொடுகை கொண்ட, நெருப்புப் போல் ஒளிரும், புண்ணியம் செய்து சொர்க்கத்தை வென்ற பெரும் பேறுடையோர் வசிக்கும்,',
        '0.176': 'அவியைச் சுமந்து செல்லும் அக்னியால் நிறைந்த, கோள்கள், நட்சத்திரங்கள், சந்திரன், சூரியன், விண்மீன் கூட்டங்களால் அலங்கரிக்கப்பட்ட,',
        '0.177': 'மகரிஷிக் கூட்டங்கள், கந்தர்வர், நாகர், யக்ஷர் நிறைந்த, விரிந்த, தூய, விஸ்வாவசு உலவும்,',
        '0.178': 'தேவராஜனின் யானை செல்லும், சந்திர சூரியரின் மங்கள வழியான, பிரம்மனால் படைக்கப்பட்ட உயிருலகின் விரிந்த மேற்கட்டி போன்ற,',
        '0.179': 'வீரர்கள் அடிக்கடி உலவும், வித்யாதரக் கூட்டங்கள் சூழ்ந்த அந்த வான்வழியில் மாருதி கருடன் போல் சென்றான்.',
        '0.180': 'ஹனுமான் காற்றைப் போல் கருமையான அகில் நிறமுடைய, சிவப்பு, மஞ்சள், வெண்மை மேகக் கூட்டங்களை இழுத்துச் சென்றான்.',
        '0.181': 'கபியால் இழுக்கப்பட்ட பெருமேகங்கள் ஒளிர்ந்தன; மேகக் கூட்டங்களில் நுழைந்து மீண்டும் மீண்டும் வெளிவந்து,',
        '0.182': 'வெளிவந்தும் உள்நுழைந்தும் எங்கும் காணப்பட்ட வாயுமைந்தன் ஹனுமான் மழைக்கால நிலவு போல் ஒளிர்ந்தான்.',
        '0.183': 'சிறகுள்ள மலையரசன் போல் அவன் ஆதாரமற்ற வானைச் சார்ந்தான். பறக்கும் அவனைக் கண்டு சிம்ஹிகை என்ற அரக்கி,',
        '0.184': 'பேருருவமும் விரும்பிய உருவெடுக்கும் திறனும் கொண்ட அவள் மனதில் எண்ணினாள்: "நீண்ட காலத்திற்குப் பின் இன்று நான் வயிறார உண்பேன்.',
        '0.185': 'இந்தப் பெரும் உயிர் நீண்ட நாளுக்குப் பின் என் வசமாகியுள்ளது." இவ்வாறு எண்ணி அவள் அவன் நிழலைப் பற்றி இழுத்தாள்.',
        '0.186': 'நிழல் பிடிக்கப்பட்டதும் கபி எண்ணினான்: "திடீரென்று நான் இழுக்கப்பட்டேன், என் வீரம் முடமாக்கப்பட்டது,',
        '0.187': 'கடலில் எதிர்க்காற்றில் சிக்கிய பெரும் கப்பல் போல்." குறுக்காகவும் மேலும் கீழும் பார்த்த அந்தக் கபி,',
        '0.188': 'உப்புக் கடலிலிருந்து எழுந்த ஒரு பெரும் உயிரைக் கண்டான். விகார முகமுடைய அவளைக் கண்டு மாருதி எண்ணினான்:',
        '0.189': '"வானர அரசன் (சுக்ரீவன்) சொன்ன அற்புதத் தோற்றமுடைய, நிழலைப் பிடிக்கும் பெரும் வலிமை கொண்ட உயிர் இதுவே; ஐயமில்லை."',
        '0.190': 'அவளை உண்மையில் சிம்ஹிகை என்று அறிந்த அறிவாளிக் கபி மழைக்கால மேகம் போல் பேருருவனாக வளர்ந்தான்.',
        '0.191': 'மகாகபியின் உடல் வளர்வதைக் கண்டு அவள் பாதாளம் முதல் வானம் வரை அளவுக்குத் தன் வாயைத் திறந்தாள்.',
        '0.192': 'மேகவரிசை போல் முழங்கியபடி அவள் கபியை நோக்கிப் பாய்ந்தாள். அப்போது அவன் அவளுடைய விகாரமான மிகப் பெரிய வாயைக் கண்டான்,',
        '0.193': 'அறிவாளியான அந்த மகாகபி அவள் உடலின் அளவையும் மர்ம இடங்களையும் அறிந்தான். வஜ்ரம் போன்ற உறுதியான உடலுடைய அந்தக் கபி அவளுடைய விகார வாய்க்குள்,',
        '0.194': 'மீண்டும் தன்னைச் சுருக்கிக் கொண்டு அந்த மகாகபி பாய்ந்தான். அவள் வாயில் மூழ்கும் அவனைச் சித்தர்களும் சாரணர்களும் கண்டனர்,',
        '0.195': 'பருவ நாளில் ராகுவால் விழுங்கப்படும் முழுநிலவு போல். பின்னர் கூர்மையான நகங்களால் அவள் மர்ம இடங்களைக் கிழித்து அந்தக் கபி,',
        '0.196': 'மனவேகம் கொண்ட வீரன் விரைவாக வெளியே எழுந்தான். நல்வாய்ப்பாலும் உறுதியாலும் திறமையாலும் அவளை வீழ்த்தி,',
        '0.197': 'தன்னடக்கமுடைய அந்தக் கபிவீரன் மீண்டும் விரைவாக வளர்ந்தான். ஹனுமானால் இதயம் பறிக்கப்பட்ட அவள் நிலைகுலைந்து நீரில் விழுந்தாள்; அவளை வீழ்த்தவே சுயம்பு ஹனுமானைப் படைத்திருந்தான்.',
        '0.198': 'கபியால் விரைவில் கொல்லப்பட்டு விழுந்த சிம்ஹிகையைக் கண்டு வானில் திரியும் உயிர்கள் அந்தக் கபிசிரேஷ்டனிடம் கூறின:',
        '0.199': '"இன்று நீ அஞ்சத்தக்க செயலைச் செய்தாய்; ஒரு பெரும் உயிரைக் கொன்றாய். தாவுவோரில் சிறந்தவனே, இடையூறின்றி உன் நோக்கத்தை நிறைவேற்று.',
        '0.200': 'வானர இந்திரனே, உன்னிடம் உள்ளது போல் உறுதி, நோக்கு, அறிவு, திறமை — இந்த நான்கும் உள்ளவன் செயல்களில் ஒருபோதும் தோற்பதில்லை."',
        '0.201': 'தம் நோக்கம் நிறைவேறிய அவர்களால் போற்றப்பட்ட அந்த மதிப்புக்குரிய கபி வானில் புகுந்து பாம்புண்ணியான கருடன் போல் சென்றான்.',
        '0.202': 'பெரும்பாலான வழியைக் கடந்து சுற்றிலும் பார்த்தபடி நூறு யோஜனையின் முடிவில் அவன் காட்டு வரிசையைக் கண்டான்.',
        '0.203': 'கீழிறங்கும்போதே அந்தக் கபிசிரேஷ்டன் பலவித மரங்களால் அலங்கரிக்கப்பட்ட தீவையும் மலய மலையின் சோலைகளையும் கண்டான்.',
        '0.204': 'கடலையும், கடற்கரைச் சதுப்பு நிலங்களையும், அங்கு வளர்ந்த மரங்களையும், கடலின் மனைவியரான நதிகளின் முகத்துவாரங்களையும் அவன் கண்டான்.',
        '0.205': 'வானையே மறைப்பது போல் பெருமேகமாக இருந்த தன்னைக் கண்டு அந்த அறிவாளி ஒரு முடிவுக்கு வந்தான்.',
        '0.206': '"என் உடல் வளர்ச்சியையும் வேகத்தையும் கண்டால் அரக்கர்கள் என்னைப் பற்றி ஆர்வம் கொள்வார்கள்" என்று அந்தப் பேரறிவாளன் எண்ணினான்.',
        '0.207': 'அப்போது மலைபோன்ற தன் உடலைச் சுருக்கிக் கொண்டு, மயக்கம் நீங்கியவன் போல் அந்தத் தன்னடக்கமுடையவன் மீண்டும் தன் இயல்பு உருவை அடைந்தான்.',
        '0.208': 'அந்த உருவை மிகவும் சுருக்கி ஹனுமான் தன் இயல்பு நிலையில் நின்றான் — மூன்றடி வைத்து பலியின் வலிமையைப் பறித்த ஹரி (விஷ்ணு) போல்.',
        '0.209': 'பலவித அழகிய உருவங்களை எடுக்க வல்ல அவன் பிறரால் இயலாத கடலின் மறுகரையை அடைந்து, தன் உருவைப் பெற்று, தன்னையும் தன் காரியத்தையும் ஆராய்ந்தான்.',
        '0.210': 'பின்னர் பெருமேகக் குவியல் போன்ற அந்த மகாத்மா தாழை, உத்தாலகம், தென்னை மரங்கள் நிறைந்த, விசித்திரச் சிகரங்களுடைய லம்ப மலையின் செழிப்பான சிகரத்தில் இறங்கினான்.',
        '0.211': 'கடற்கரையை அடைந்து சிறந்த மலையின் உச்சியில் இருந்த இலங்கையைக் கண்டு, அந்தக் கபி தன் உருவை உதறி விலங்குகளையும் பறவைகளையும் அஞ்சச் செய்தபடி அந்த மலையில் இறங்கினான்.',
        '0.212': 'தானவர்களும் நாகங்களும் நிறைந்த, பேரலைகளை மாலையாகக் கொண்ட கடலை வலிமையால் கடந்து, பெருங்கடலின் கரையில் இறங்கி அவன் அமராவதி போன்ற இலங்கையைக் கண்டான்.',
        '0.213': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் முதல் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-02': {
      verses: {
        '0.0': 'வெல்ல முடியாத கடலைக் கடந்த அந்த மகாபலசாலி திரிகூட மலைச்சரிவில் அமைதியாக நின்று இலங்கையை நோக்கினான்.',
        '0.1': 'அங்கே மரங்களிலிருந்து உதிர்ந்த மலர் மழையால் நனைந்த அந்த வீரக் கபி மலர்களாலேயே ஆனவன் போல் விளங்கினான்.',
        '0.2': 'நூறு யோஜனை கடந்தும் அந்த ஒளிமிக்க மாவீரக் கபி மூச்சு வாங்கவும் இல்லை, களைப்படையவும் இல்லை.',
        '0.3': '"நான் பல நூறு யோஜனைகளையும் கடக்க முடியும்; நூறு யோஜனை என்று கணக்கிடப்பட்ட கடலின் கரை பற்றிச் சொல்வானேன்?" என்று அவன் எண்ணினான்.',
        '0.4': 'வீரர்களில் சிறந்தவனும் தாவுவோரில் உத்தமனுமான அவன் பெருங்கடலைக் கடந்து விரைவாக இலங்கையை நோக்கிச் சென்றான்.',
        '0.5': 'பசும் புல்வெளிகள் வழியாகவும், மணமும் தேனும் நிறைந்த, மரங்கள் அடர்ந்த காடுகள் வழியாகவும் அவன் சென்றான்.',
        '0.6': 'ஒளிமிக்க வானர சிரேஷ்டன் ஹனுமான் மரங்கள் அடர்ந்த குன்றுகளையும் பூத்த வனவரிசைகளையும் கடந்து சென்றான்.',
        '0.7': 'அந்த மலையில் நின்ற வாயுபுத்திரன் காடுகளையும் சோலைகளையும் மலையுச்சியில் இருந்த இலங்கையையும் கண்டான்.',
        '0.8': 'பூத்த சரளம், கர்ணிகாரம், பேரீச்சை, பிரியாளம், முசுலிந்தம், குடஜம், தாழை மரங்களையும்,',
        '0.9': 'மணமிக்க பிரியங்கு, கடம்பு, ஏழிலைப்பாலை, அசனம், கோவிதாரம், பூத்த அலரி மரங்களையும்,',
        '0.10': 'மலர்ச் சுமையால் வளைந்த, மொட்டுகள் நிறைந்த, பறவைகள் நிறைந்த, காற்றில் உச்சிகள் அசையும் மரங்களையும்,',
        '0.11': 'அன்னங்களும் காரண்டவங்களும் நிறைந்த, தாமரைகளும் அல்லிகளும் மூடிய குளங்களையும், பலவித இனிய விளையாட்டிடங்களையும் நீர்நிலைகளையும்,',
        '0.12': 'எல்லாப் பருவங்களிலும் பழமும் பூவும் தரும் பலவித மரங்கள் நிறைந்த இனிய தோட்டங்களையும் அந்தக் கபிசிரேஷ்டன் கண்டான்.',
        '0.13': 'அந்த ஒளிமிக்கவன் தாமரைகளும் அல்லிகளும் நிறைந்த அகழிகளால் அலங்கரிக்கப்பட்ட, ராவணன் ஆளும் இலங்கையை அணுகினான்;',
        '0.14': 'சீதையைக் கவர்ந்ததால் ராவணன் அதனைக் கடுமையாகக் காத்து வந்தான்; கொடிய வில்லேந்திய அரக்கர்கள் சுற்றிலும் திரிந்தனர்;',
        '0.15': 'பொன் மதிலால் சூழப்பட்ட, மலைகளைப் போன்ற, கூதிர்கால மேகம் போன்ற வீடுகளுடைய அழகிய பெருநகரம்;',
        '0.16': 'உயர்ந்த வெண்மையான தெருக்களால் சூழப்பட்ட, நூற்றுக்கணக்கான கோபுரங்கள் நிறைந்த, கொடிகளும் பதாகைகளும் விளங்கும்,',
        '0.17': 'கொடிவரிசைகளால் விளங்கும் தெய்வீகப் பொன் தோரணங்கள் கொண்ட இலங்கையை ஹனுமான் ஒரு தேவன் தேவநகரத்தைப் பார்ப்பது போல் பார்த்தான்.',
        '0.18': 'மலையுச்சியில் அழகிய வெண்மாளிகைகளுடன் இருந்த இலங்கையை அந்த ஒளிமிக்க கபி வானில் மிதக்கும் நகரம் போல் கண்டான்.',
        '0.19': 'அரக்கர் அரசனால் ஆளப்படும், விஸ்வகர்மாவால் கட்டப்பட்ட அந்நகரம் வானில் மிதப்பது போல் ஹனுமானுக்குத் தோன்றியது.',
        '0.20': 'கோட்டைச் சுவர்களே அவளுடைய இடை, பரந்த நீரும் காடுமே அவள் ஆடை, சதக்னிகளும் சூலங்களுமே அவள் கூந்தல், கோபுரங்களே அவள் காதணிகள்.',
        '0.21': 'மனத்தாலேயே படைத்தது போன்ற, விஸ்வகர்மா கட்டிய இலங்கையின் வடக்கு வாயிலை அடைந்து அந்த வானரன் சிந்தித்தான்.',
        '0.22': 'அது கைலாச இருப்பிடம் போன்று, வானைக் கீறுவது போலவும், உயர்ந்த சிறந்த மாளிகைகளால் வானைத் தாங்குவது போலவும் இருந்தது.',
        '0.23': 'நாகங்கள் நிறைந்த போகவதி போல் கொடிய அரக்கர்கள் நிறைந்த அந்நகரம் சிந்தனைக்கெட்டாதது, நன்கு கட்டப்பட்டது, ஒழுங்கானது; முன்பு குபேரன் வாழ்ந்த இடம்.',
        '0.24': 'நச்சுப் பாம்புகள் குகையைக் காப்பது போல் கோரைப்பற்கள் கொண்ட, சூலமும் பட்டிசமும் ஏந்திய பல வீரமிக்க கொடிய அரக்கர்கள் அதைக் காத்தனர்.',
        '0.25': 'அதன் பெரும் பாதுகாப்பையும், கடலையும், கொடிய பகைவன் ராவணனையும் கண்டு அந்த வானரன் எண்ணினான்:',
        '0.26': '"வானரர்கள் இங்கு வந்தாலும் பயனில்லை; போரால் இலங்கையைத் தேவர்களாலும் வெல்ல முடியாது.',
        '0.27': 'ராவணன் ஆளும் இந்தக் கடினமான அரண் சூழ்ந்த இலங்கையை அடைந்தாலும் நீண்ட கரமுடைய ராகவன் என்ன செய்ய முடியும்?',
        '0.28': 'அரக்கர்களிடம் சாமத்திற்கு இடமில்லை, தானத்திற்கும் இல்லை, பேதத்திற்கும் இல்லை, போருக்கும் வழி தெரியவில்லை.',
        '0.29': 'வேகமுடைய வானரர்களில் நால்வருக்கே இங்கு வரும் ஆற்றல் உண்டு — வாலியின் மகன் (அங்கதன்), நீலன், நான், அறிவுள்ள எம் அரசன் (சுக்ரீவன்).',
        '0.30': 'முதலில் வைதேஹி உயிருடன் இருக்கிறாளா இல்லையா என்று அறிவேன்; ஜனகனின் மகளைக் கண்ட பின் அங்கேயே அடுத்ததைச் சிந்திப்பேன்."',
        '0.31': 'பின்னர் அந்த மலைச்சிகரத்தில் நின்ற கபிசிரேஷ்டன் ராமனின் வெற்றியைப் பற்றிச் சிறிது நேரம் சிந்தித்தான்.',
        '0.32': '"இந்த உருவத்துடன் கொடியவர்களும் வலியவர்களுமான அரக்கர்கள் காக்கும் அரக்கர் நகரத்திற்குள் என்னால் நுழைய முடியாது.',
        '0.33': 'அரக்கர்கள் பேராற்றலும் பெரும் வீரமும் வலிமையும் உடையவர்கள்; ஜானகியைத் தேடும்போது நான் அவர்கள் அனைவரையும் ஏமாற்ற வேண்டும்.',
        '0.34': 'என் பெரும் காரியத்தை நிறைவேற்ற இரவில், தெரிந்தும் தெரியாத உருவத்துடன் இலங்கைக்குள் நுழைவதே தக்க நேரம்."',
        '0.35': 'தேவர்களாலும் அசுரர்களாலும் வெல்ல முடியாத அந்நகரைக் கண்டு ஹனுமான் மீண்டும் மீண்டும் பெருமூச்சு விட்டுச் சிந்தித்தான்:',
        '0.36': '"தீயவனான அரக்கர் அரசன் ராவணன் கண்ணில் படாமல் ஜனகனின் மகள் மைதிலியை எந்த உபாயத்தால் காண்பேன்?',
        '0.37': 'தன்னை அறிந்த ராமனின் காரியம் எப்படிக் கெடாமல் இருக்கும்? தனிமையில் தனியாக இருக்கும் ஜனகன் மகளை நான் தனியே எப்படிக் காண்பேன்?',
        '0.38': 'இடத்துக்கும் காலத்துக்கும் முரணாகத் தடுமாறும் தூதனிடம் சிக்கினால், நிறைவேறிய காரியங்களும் சூரிய உதயத்தில் இருள் போல் அழிந்துவிடும்.',
        '0.39': 'நன்மை தீமை பற்றிய உறுதியான முடிவும் பயனின்றிப் போகும்; தம்மைப் பண்டிதர் என்று எண்ணும் தூதர்கள் காரியங்களைக் கெடுப்பார்கள்.',
        '0.40': 'காரியம் எப்படிக் கெடாமல் இருக்கும்? தவறு எப்படி நேராமல் இருக்கும்? கடலைக் கடந்தது எப்படி வீணாகாமல் இருக்கும்?',
        '0.41': 'அரக்கர்கள் என்னைக் கண்டால் ராவணனின் அழிவை விரும்பும் ராமனின் இந்தக் காரியம் வீணாகிவிடும்.',
        '0.42': 'அரக்க உருவில் இருந்தாலும் அரக்கர்கள் அறியாமல் இங்கு எங்கும் தங்க முடியாது; வேறு உருவைப் பற்றிச் சொல்லவேண்டுமா?',
        '0.43': 'இங்கே காற்றும் அறியப்படாமல் வீச முடியாது என்பது என் எண்ணம்; கொடுஞ்செயல் அரக்கர்களுக்குத் தெரியாதது இங்கு எதுவும் இல்லை.',
        '0.44': 'என் சொந்த உருவிலேயே இங்கு இருந்தால் நான் அழிவேன், என் தலைவனின் காரியமும் கெடும்.',
        '0.45': 'ஆகவே இரவில் என் உருவையே சிறிதாக்கிக் கொண்டு ராகவனின் காரிய சித்திக்காக இலங்கைக்குள் பாய்வேன்.',
        '0.46': 'அணுகுவதற்கரிய ராவணனின் நகரத்தில் இரவில் நுழைந்து, எல்லா மாளிகைகளிலும் புகுந்து ஜனகன் மகளைக் காண்பேன்."',
        '0.47': 'இவ்வாறு முடிவு செய்து வைதேஹியைக் காணும் ஆவலுடன் வீரக் கபி ஹனுமான் சூரியன் மறைவதற்குக் காத்திருந்தான்.',
        '0.48': 'சூரியன் மறைந்ததும் இரவில் மாருதி உடலைச் சுருக்கிப் பூனை அளவினனாகி அற்புதமாகத் தோன்றினான்.',
        '0.49': 'அந்திப் பொழுதில் வீரன் ஹனுமான் விரைந்து தாவி, நன்கு பிரிக்கப்பட்ட ராஜவீதிகள் கொண்ட அழகிய நகரத்தில் நுழைந்தான்;',
        '0.50': 'மாளிகை வரிசைகள் நிறைந்த, பொன்னிறத் தூண்களும் பொன் சாளரங்களும் கொண்ட அது கந்தர்வ நகரம் போல் இருந்தது.',
        '0.51': 'ஏழு எட்டு மாடி வீடுகளும், பளிங்கு பதித்துப் பொன்னால் அலங்கரித்த தளங்களும் கொண்ட அந்தப் பெருநகரை அவன் கண்டான்.',
        '0.52': 'வைடூரியக் கற்களால் சித்திரிக்கப்பட்ட, முத்துச் சரங்களால் அலங்கரிக்கப்பட்ட தளங்களால் அங்குள்ள அரக்கர்களின் மாளிகைகள் விளங்கின.',
        '0.53': 'அரக்கர்களின் விசித்திரமான பொன் தோரணங்கள் எங்கும் அலங்கரிக்கப்பட்ட இலங்கையை ஒளிரச் செய்தன.',
        '0.54': 'சிந்தனைக்கெட்டாத அற்புத வடிவுடைய இலங்கையைக் கண்டு வைதேஹியைக் காணும் ஆவலுடைய மகாகபி வருந்தவும் செய்தான், மகிழவும் செய்தான்.',
        '0.55': 'வெண்மையான விமான மாளிகை வரிசைகள் கொண்ட, விலையுயர்ந்த பொன் வலைத் தோரணங்கள் கொண்ட, ராவணனின் கரங்களால் காக்கப்பட்ட, கொடிய வலிமையுள்ள இரவுலாவிகளால் நன்கு காக்கப்பட்ட அந்தப் புகழ்மிக்க நகரை அவன் கண்டான்.',
        '0.56': 'அவனுக்கு உதவுவது போல், விண்மீன் கூட்டங்களின் நடுவே ஒளிர்ந்து, நிலவொளிப் போர்வையால் உலகங்களை மூடியபடி ஆயிரக்கணக்கான கதிர்கள் கொண்ட சந்திரனும் உதித்தான்.',
        '0.57': 'சங்கு போன்ற ஒளியுடைய, பாலும் தாமரைத் தண்டும் போல் வெண்மையான, உதித்து ஒளிரும் சந்திரனை அந்தக் கபிவீரன் ஏரியில் மிதக்கும் அன்னம் போல் கண்டான்.',
        '0.58': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் இரண்டாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-03': {
      verses: {
        '0.0': 'உயர்ந்த மேகம் போன்ற லம்ப மலைச் சிகரத்தில் அறிவாளியான வாயுபுத்திரன் ஹனுமான் துணிவைக் கொண்டு,',
        '0.1': 'அந்த மகா வலிமையுள்ள கபிசிரேஷ்டன் இரவில் அழகிய காடுகளும் நீர்வளமும் கொண்ட, ராவணன் ஆளும் இலங்கை நகருக்குள் நுழைந்தான்;',
        '0.2': 'கூதிர்கால மேகங்கள் போன்ற மாளிகைகளால் விளங்கும், கடல் போல் முழங்கும், கடற்காற்று வீசும்,',
        '0.3': 'விடபாவதி (குபேரன் நகரம்) போல் வலிமையான படைகள் நிறைந்த, அழகிய தோரணங்களும் மாடங்களும், வெண்மையான வாயில்களும் கொண்ட,',
        '0.4': 'அழகிய போகவதி போல் நாகங்கள் உலவும், நன்கு காக்கப்பட்ட, மின்னலுடைய மேகங்கள் நிறைந்த, விண்மீன் கூட்டங்கள் சூழ்ந்த,',
        '0.5': 'அமராவதி போல் கடுங்காற்றின் முழக்கமுடைய, பெரிய பொன் மதிலால் சூழப்பட்ட,',
        '0.6': 'சிறு மணிகளின் ஒலியுடைய கொடிகளால் அலங்கரிக்கப்பட்ட அந்நகரை அடைந்து, மகிழ்ந்து அவன் திடீரென்று மதில்மேல் ஏறினான்.',
        '0.7': 'வியப்பு நிறைந்த உள்ளத்துடன் அவன் நகரைச் சுற்றிலும் நோக்கினான் — வைடூரிய மேடைகளுடைய பொன் வாயில்களையும்,',
        '0.8': 'வைரம், பளிங்கு, முத்துக்களாலும் மணித் தளங்களாலும் அலங்கரிக்கப்பட்ட, புடம்போட்ட பொன் மாடங்களும் தூய வெண்ணிற வெள்ளியும் கொண்ட,',
        '0.9': 'வைடூரியப் படிகளும், பளிங்குத் தூள் பரப்பிய முற்றங்களும், அழகிய சபைக் கூடங்களும் கொண்ட, வானில் எழுவது போன்ற அழகிய மாளிகைகளையும்,',
        '0.10': 'அன்றில்களும் மயில்களும் கூவும், ராஜஹம்சங்கள் உலவும், இசைக்கருவிகளும் அணிகலன்களும் ஒலிக்கும் எங்கும் முழங்கும் நகரை.',
        '0.11': 'இந்திரனின் நகரம் போன்ற, வானில் எழுந்தது போன்ற இலங்கை நகரைக் கண்டு கபி ஹனுமான் மகிழ்ந்தான்.',
        '0.12': 'அரக்கர் தலைவனின் அந்த அழகிய, நிகரற்ற, செழிப்பான இலங்கை நகரைக் கண்டு அந்த வீரன் சிந்தித்தான்:',
        '0.13': '"ஆயுதங்களை ஏந்திய ராவணனின் படைகளால் காக்கப்படும் இந்நகரை வேறு யாரும் வலிமையால் கைப்பற்ற முடியாது.',
        '0.14': 'குமுதன், அங்கதன், மகாகபி சுஷேணன், மைந்தன், த்விவிதன் ஆகியோருக்கு இந்நிலம் எட்டக்கூடியதாக இருக்கலாம்;',
        '0.15': 'விவஸ்வானின் மகனுக்கும் (சுக்ரீவனுக்கும்), கபி குசபர்வனுக்கும், கபிமுக்கியன் ரிக்ஷனுக்கும், எனக்கும் இங்கு வர முடியும்."',
        '0.16': 'பின்னர் நீண்ட கரமுடைய ராகவனின் வீரத்தையும் லக்ஷ்மணனின் ஆற்றலையும் எண்ணி அந்தக் கபி மகிழ்ந்தான்.',
        '0.17': 'ரத்தினங்களே ஆடை, களஞ்சியங்களே காதணி, இயந்திரக் கூடங்களே மார்பகங்கள் — இவ்வாறு அலங்கரித்த இளம்பெண் போன்ற செழிப்பான நகரை,',
        '0.18': 'விளக்குகளாலும் ஒளிரும் பெரும் கோள்களாலும் இருள் நீங்கிய அந்த அரக்கர் அரசனின் நகரை அந்த மகாகபி கண்டான்.',
        '0.19': 'அப்போது அந்நகரமே தன் சொந்த உருவில், நுழைந்து கொண்டிருந்த கபிசார்தூலனான மகாகபி வாயுபுத்திரனைக் கண்டாள்.',
        '0.20': 'அந்த வானர சிரேஷ்டனைக் கண்டு ராவணன் ஆளும் இலங்கை விகார முகத்துடன் தானே அங்கு எழுந்து நின்றாள்.',
        '0.21': 'அந்த வீர வாயுபுத்திரன் முன் நின்று பெருமுழக்கமிட்டு அவள் அவனிடம் கூறினாள்:',
        '0.22': '"வனவாசியே, நீ யார்? எந்தக் காரியத்திற்காக இங்கு வந்தாய்? உன் உயிர் இருக்கும்போதே உண்மையைச் சொல்.',
        '0.23': 'வானரனே, இந்த இலங்கைக்குள் நீ நுழைய முடியாது; இது ராவணனின் படைகளால் எங்கும் காக்கப்படுகிறது."',
        '0.24': 'அப்போது வீரன் ஹனுமான் தன் முன் நின்ற அவளிடம் கூறினான்: "நீ கேட்கும் உண்மையைச் சொல்வேன்.',
        '0.25': 'விகாரக் கண்களுடைய நீ யார்? நகர வாயிலில் ஏன் நிற்கிறாய்? கொடியவளே, சினத்துடன் என்னை ஏன் மிரட்டுகிறாய்?"',
        '0.26': 'ஹனுமானின் சொல்லைக் கேட்டு விரும்பிய உருவெடுக்கும் இலங்கை சினத்துடன் வாயுபுத்திரனிடம் கடுமையாகக் கூறினாள்:',
        '0.27': '"வெல்லப்பட முடியாத நான் மகாத்மாவான அரக்கர் அரசன் ராவணனின் ஆணையை எதிர்பார்த்து இந்நகரைக் காக்கிறேன்.',
        '0.28': 'என்னைப் புறக்கணித்து இந்நகருக்குள் நுழைய முடியாது; இன்று என்னால் கொல்லப்பட்டு உயிரற்றவனாகக் கிடப்பாய்.',
        '0.29': 'வானரனே, நானே இலங்கை நகரம்; எல்லாப் பக்கங்களிலும் இதைக் காக்கிறேன். அதனால்தான் உனக்கு இதைச் சொன்னேன்."',
        '0.30': 'இலங்கையின் சொல்லைக் கேட்டு வாயுபுத்திரனான கபிசிரேஷ்டன் ஹனுமான் விழிப்புடன் இன்னொரு மலை போல் அசையாமல் நின்றான்.',
        '0.31': 'பெண் உருவில் விகாரமாக இருந்த அவளைக் கண்டு அறிவும் வலிமையும் கொண்ட வானர சிரேஷ்டன் கூறினான்:',
        '0.32': '"கோபுரங்களும் மதில்களும் தோரணங்களும் கொண்ட இலங்கை நகரைக் காணவே இங்கு வந்தேன்; எனக்குப் பெரும் ஆர்வம் உள்ளது.',
        '0.33': 'இலங்கையின் காடுகளையும் சோலைகளையும் வனங்களையும் சுற்றியுள்ள முக்கிய மாளிகைகளையும் காண நான் வந்தேன்."',
        '0.34': 'அவன் சொல்லைக் கேட்டு விரும்பிய உருவெடுக்கும் இலங்கை மீண்டும் கடுஞ்சொற்கள் கூறினாள்:',
        '0.35': '"தீய புத்தியுடையவனே, வானரரில் இழிந்தவனே, என்னை வெல்லாமல் அரக்கர் அரசன் ஆளும் இந்நகரை இன்று நீ காண முடியாது."',
        '0.36': 'அப்போது அந்தக் கபிசார்தூலன் அந்த இரவுலாவியிடம் கூறினான்: "நல்லவளே, இந்நகரைக் கண்டுவிட்டு வந்த வழியே திரும்பிச் செல்வேன்."',
        '0.37': 'அப்போது இலங்கை அச்சமூட்டும் பெருமுழக்கமிட்டு விரைவாக உள்ளங்கையால் அந்த வானர சிரேஷ்டனை அறைந்தாள்.',
        '0.38': 'இலங்கையால் வலுவாக அறையப்பட்ட வீரக் கபிசார்தூலன் வாயுபுத்திரன் பெருமுழக்கமிட்டான்.',
        '0.39': 'அப்போது சினம் பொங்கிய ஹனுமான் இடக்கை விரல்களை மடக்கி முஷ்டியால் அவளை அடித்தான்.',
        '0.40': '"இவள் பெண்" என்று எண்ணி அவன் மிகுந்த சினம் கொள்ளவில்லை; எனினும் அந்த அடியால் விகார முகமுடைய அந்த இரவுலாவி உறுப்புகள் தளர்ந்து திடீரென்று தரையில் விழுந்தாள்.',
        '0.41': 'விழுந்து கிடந்த அவளைக் கண்டு, அவள் பெண் என்று எண்ணி ஒளிமிக்க வீரன் ஹனுமான் இரக்கம் கொண்டான்.',
        '0.42': 'அப்போது மிகவும் கலங்கிய இலங்கை செருக்கை விட்டுத் தழுதழுத்த குரலில் கபி ஹனுமானிடம் கூறினாள்:',
        '0.43': '"நீண்ட கரமுடையவனே, அருள்புரி; ஹரிசத்தமனே, என்னைக் காப்பாற்று. சாந்தனே, வலிமைமிக்க வீரர்கள் நெறியைக் கடைப்பிடிப்பார்கள்.',
        '0.44': 'வானரனே, நானே இலங்கை நகரம்; பெரும் வலிமையுள்ள வீரனே, உன் வீரத்தால் நான் வெல்லப்பட்டேன்.',
        '0.45': 'வானர அரசே, நான் சொல்லும் இந்த உண்மையைக் கேள் — சுயம்பு தானே எனக்கு அளித்த வரம் இது:',
        '0.46': '\'எப்போது ஏதேனும் ஒரு வானரன் வீரத்தால் உன்னை அடக்குகிறானோ, அப்போது அரக்கர்களுக்கு அழிவு வந்துவிட்டது என்று அறிந்துகொள்.\'',
        '0.47': 'சாந்தனே, சுயம்பு விதித்த அந்த நேரம் இன்று உன் வருகையால் வந்துவிட்டது; அது உண்மை, அதை மீற முடியாது.',
        '0.48': 'சீதையின் காரணமாகத் தீய அரசன் ராவணனுக்கும் எல்லா அரக்கர்களுக்கும் அழிவு நெருங்கிவிட்டது.',
        '0.49': 'ஆகவே ஹரிசிரேஷ்டனே, ராவணன் ஆளும் நகருக்குள் நுழைந்து இங்கு நீ விரும்பும் எல்லாக் காரியங்களையும் செய்.',
        '0.50': 'வானர அரசே, சாபத்தால் தாக்கப்பட்ட, அரக்கர் தலைவன் ஆளும் இந்த அழகிய நகருக்குள் நுழைந்து, எங்கும் இன்பமாகத் திரிந்து, கற்புடைய ஜனகன் மகளை விரும்பியபடி தேடு."',
        '0.51': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் மூன்றாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-04': {
      verses: {
        '0.0': 'விரும்பிய உருவெடுக்கும் அந்தச் சிறந்த இலங்கை நகரைத் தன் வீரத்தால் வென்று, பேரொளி கொண்ட கபிசிரேஷ்டன் ஹனுமான்,',
        '0.1': 'அந்த மாவீரன் வாயில் வழியாக அல்லாமல் மதிலைத் தாண்டினான்; இரவில் அந்த மகா வலிமையுள்ள கபிசிரேஷ்டன் இலங்கைக்குள் நுழைந்தான்.',
        '0.2': 'இலங்கை நகருக்குள் நுழைந்த வானர அரசனின் நலம் விரும்பி பகைவர்களின் தலைமேலேயே தன் இடக்காலை வைத்தான்.',
        '0.3': 'இரவில் நுழைந்த வலிமை நிறைந்த வாயுபுத்திரன் தூவிய மலர்களால் விளங்கிய ராஜவீதியைப் பற்றி,',
        '0.4': 'சிரிப்பொலிகளும் உரத்த கூச்சல்களும் இசைக்கருவி முழக்கங்களும் நிறைந்த அந்த அழகிய இலங்கை நகரில் அந்தக் கபி சென்றான்.',
        '0.5': 'வஜ்ரம், அங்குசம் போன்ற அடையாளங்கள் கொண்ட, வைரச் சாளரங்களால் அலங்கரிக்கப்பட்ட மேகம் போன்ற வீடுகளால் அந்நகரம் மேகங்கள் நிறைந்த வானம் போல் விளங்கியது.',
        '0.6': 'வெண்மேகம் போன்ற, பலவண்ண, தாமரை ஸ்வஸ்திக வடிவில் கட்டப்பட்ட அரக்கர்களின் அழகிய வீடுகளால் இலங்கை ஒளிர்ந்தது;',
        '0.7': 'எங்கும் நன்கு அலங்கரிக்கப்பட்ட \'வர்த்தமான\' வீடுகளாலும் நிறைந்திருந்தது. விசித்திர மாலைகளும் அணிகலன்களும் கொண்ட அந்நகரை வானர அரசனின் நலம் விரும்பி,',
        '0.8': 'ராகவனுக்காகத் திரிந்தபடி கண்டு மகிழ்ந்தான். வீடு வீடாகச் சென்ற அந்தக் கபிசிரேஷ்டன் கண்டான் —',
        '0.9': 'ஆங்காங்கே பலவித வடிவங்களும் தோற்றங்களும் கொண்ட மாளிகைகளை. மூன்று ஸ்தாயிகளின் ஸ்வரங்களால் அழகுற்ற இனிய பாடலை அவன் கேட்டான்,',
        '0.10': 'சொர்க்கத்து அப்சரஸ்கள் போல் காமவயப்பட்ட பெண்கள் பாடினர். ஒட்டியாணங்களின் ஓசையையும் சிலம்புகளின் ஒலியையும் கேட்டான்,',
        '0.11': 'பெரியோரின் மாளிகைகளில் படிகளில் காலடி ஓசையையும், ஆங்காங்கே தோள் தட்டும் ஒலியையும் சிம்மநாதங்களையும் கேட்டான்.',
        '0.12': 'அரக்கர்களின் வீடுகளில் மந்திரங்களை ஜபிப்போரைக் கேட்டான்; வேதம் ஓதுவதில் ஈடுபட்ட யாதுதானர்களையும் கண்டான்,',
        '0.13': 'ராவணனின் புகழை முழங்கும் அரக்கர்களையும் கண்டான். ராஜவீதியை நிறைத்து நின்ற பெரும் அரக்கர் கூட்டத்தைக் கண்டான்.',
        '0.14': 'நடுவிலுள்ள காவல் நிலையில் அரக்கர் அரசனின் பல ஒற்றர்களைக் கண்டான் — தீட்சை பெற்றவர், சடைமுடியினர், மொட்டையடித்தவர், பசுத்தோல் அணிந்தவர்,',
        '0.15': 'தர்ப்பைக் கைப்பிடியை ஆயுதமாகக் கொண்டவர், அக்னிகுண்டத்தையே ஆயுதமாக உடையவர், சுத்தியும் கதையும் ஏந்தியவர், தண்டம் தாங்கியவர்,',
        '0.16': 'ஒற்றைக் கண்ணர், பல காதுடையோர், தொங்கும் வயிறும் மார்பும் உடையோர், கொடூரர், கோணல் வாயர், விகாரமானோர், குள்ளர்,',
        '0.17': 'வில்லாளிகள், வாளேந்தியோர், சதக்னியும் உலக்கையும் ஆயுதமாகக் கொண்டோர், சிறந்த இரும்புத் தடிகளை ஏந்தியோர், விசித்திரக் கவசங்களால் ஒளிர்வோர்,',
        '0.18': 'மிகப் பருத்தோரும் மிக மெலிந்தோரும் அல்லாதோர், மிக உயரமும் மிகக் குட்டையும் அல்லாதோர், மிக வெளுப்பும் மிகக் கருப்பும் அல்லாதோர், கூனரும் குள்ளரும் அல்லாதோர்,',
        '0.19': 'அருவருப்பானோர், பல உருவினர், அழகிய உருவினர், ஒளிமிக்கோர், கொடிகளும் பதாகைகளும் பலவித ஆயுதங்களும் ஏந்தியோரை அவன் கண்டான்;',
        '0.20': 'ஈட்டிகளையும் மரங்களையும் ஆயுதமாகக் கொண்டோரையும், பட்டிசமும் இடியும் தாங்கியோரையும், கவண்களும் பாசங்களும் கையிலேந்தியோரையும் அந்த மகாகபி கண்டான்.',
        '0.21': 'பலர் மாலைகள் அணிந்து, சந்தனம் பூசி, சிறந்த அணிகலன்களால் அலங்கரித்து, பலவித வேடங்களில் விருப்பப்படி திரிந்தனர்;',
        '0.22': 'வலியோர் கூர்மையான சூலங்களையும் வஜ்ரங்களையும் ஏந்தியிருந்தனர். விழிப்புடன் இருந்த நூறாயிரம் பேர் கொண்ட நடுக் காவல் படையைக் கபி கண்டான்,',
        '0.23': 'அரக்கர் தலைவனால் அந்தப்புரத்தின் முன் நிறுத்தப்பட்டது. அப்போது சிறந்த பொன் தோரணங்கள் கொண்ட அந்த மாளிகையைக் கண்டு,',
        '0.24': 'மலையுச்சியில் அமைந்த, வெண்தாமரைகளால் அலங்கரிக்கப்பட்ட அகழிகளால் சூழப்பட்ட அரக்கர் அரசனின் புகழ்பெற்ற மாளிகையை,',
        '0.25': 'உயர்ந்த மதிலால் சூழப்பட்ட, சொர்க்கம் போல் தெய்வீகமான, தெய்வீக ஒலிகளால் முழங்கும் அதை அந்த மகாகபி கண்டான்;',
        '0.26': 'குதிரைகளின் கனைப்பாலும் அணிகலன்களின் ஒலியாலும் முழங்கும், தேர்கள், வாகனங்கள், விமானங்கள், அழகிய குதிரைகள், யானைகள் நிறைந்த,',
        '0.27': 'வெண்மேகக் குவியல் போன்ற நான்கு தந்த யானைகளாலும் மதம் கொண்ட விலங்கு பறவைகளாலும் அலங்கரிக்கப்பட்ட அழகிய வாயில்கள் கொண்ட,',
        '0.28': 'ஆயிரக்கணக்கான மாவீர யாதுதானர்களால் காக்கப்பட்ட அரக்கர் தலைவனின் அந்தப் பாதுகாக்கப்பட்ட மாளிகைக்குள் கபி நுழைந்தான்.',
        '0.29': 'பொன் சுற்றுமதிலுடைய, விலையுயர்ந்த முத்துக்களாலும் மணிகளாலும் உள்ளே அலங்கரிக்கப்பட்ட, சிறந்த கருஅகிலும் சந்தனமும் மணக்கும் ராவணனின் அந்தப்புரத்தில் அவன் நுழைந்தான்.',
        '0.30': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் நான்காம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-05': {
      verses: {
        '0.0': 'பின்னர் அந்த அறிவாளி வானின் நடுவே சென்று, பூமியின் மேல் நிலவொளிப் போர்வையை மீண்டும் மீண்டும் பொழியும் கதிர்கள் கொண்ட சந்திரனை, கொட்டிலில் திரியும் மதம்கொண்ட காளை போல் கண்டான்.',
        '0.1': 'உலகின் பாவங்களை அழித்தும், பெருங்கடலைப் பொங்கச் செய்தும், எல்லா உயிர்களையும் ஒளிரச் செய்தும் முன்னேறும் குளிர்க்கதிர் சந்திரனை அவன் கண்டான்.',
        '0.2': 'பூமியில் மந்தர மலையிலும், அந்தியில் கடலிலும், நீரில் தாமரையிலும் எந்த அழகு ஒளிர்கிறதோ, அதே அழகு எழில்மிகு சந்திரனில் ஒளிர்ந்தது.',
        '0.3': 'வெள்ளிக் கூண்டில் அன்னம் போலும், மந்தர மலைக் குகையில் சிங்கம் போலும், செருக்குடைய யானைமேல் வீரன் போலும் வானில் சந்திரன் விளங்கினான்.',
        '0.4': 'கூர்கொம்புடைய நிற்கும் காளை போலும், உயர்ந்த சிகரங்களுடைய வெண்மலை போலும், பொன் பூண் அணிந்த தந்தங்களுடைய யானை போலும் முழுக்கலை நிலவு விளங்கியது.',
        '0.5': 'குளிர், பனி, உறைபனி என்ற சேறு நீங்கிய, பெருங்கோள் (ராகு) பிடியின் கறை நீங்கிய, ஒளித்திருவுக்கு உறைவிடமாகித் தூய்மையான அடையாளம் கொண்ட முயல்குறி பகவான் சந்திரன் ஒளிர்ந்தான்.',
        '0.6': 'பாறைத் தளத்தை அடைந்த சிங்கம் போலும், பெருங்காட்டை அடைந்த யானையரசன் போலும், நாட்டைப் பெற்ற அரசன் போலும் ஒளிமிக்க சந்திரன் விளங்கினான்.',
        '0.7': 'ஒளிமிக்க சந்திரோதயத்தால் இருள் நீங்கிய, ஊனுண்ணும் அரக்கர்களின் தீமை பெருகிய, காதலியரால் காதலர் உள்ளம் கிளர்ந்த அந்த மங்கள அந்திப்பொழுது சொர்க்கம் போல் ஒளிர்ந்தது.',
        '0.8': 'செவிக்கினிய வீணை ஒலிகள் எழுந்தன; நல்லொழுக்கப் பெண்கள் கணவருடன் உறங்கினர்; மிக அற்புதமும் கொடுமையும் கொண்ட நடத்தையுடைய இரவுலாவிகள் உலவப் புறப்பட்டனர்.',
        '0.9': 'மதுவால் மயங்கியோரும் கவனமற்றோரும் நிறைந்த, தேர்கள், குதிரைகள், சிறந்த இருக்கைகள் நெருங்கிய, வீரச் செல்வம் நிறைந்த இல்லங்களை அந்த அறிவாளிக் கபி கண்டான்.',
        '0.10': 'அவர்கள் ஒருவரையொருவர் பெரிதும் ஏளனம் செய்தனர், பருத்த கைகளை வீசினர், போதை உளறல்களை உதிர்த்தனர், போதையில் ஒருவரையொருவர் இகழ்ந்தனர்.',
        '0.11': 'அரக்கர்கள் மார்பை நிமிர்த்தினர், காதலியர் மேல் அவயவங்களைப் படரவிட்டனர், விசித்திர உருவங்களை எடுத்தனர், உறுதியான விற்களை இழுத்தனர்.',
        '0.12': 'சில பெண்கள் நறுமணம் பூசிக்கொள்வதையும், சிலர் உறங்குவதையும், அழகிய முகத்தினர் சிரிப்பதையும், வேறு சிலர் சினத்துடன் பெருமூச்சு விடுவதையும் அவன் கண்டான்.',
        '0.13': 'பிளிறும் பெரும் யானைகளாலும், போற்றப்பட்ட நல்லோராலும், பெருமூச்சு விடும் வீரர்களாலும் அந்நகரம் சீறும் பாம்புகள் நிறைந்த ஏரி போல் விளங்கியது.',
        '0.14': 'அந்நகரில் அறிவில் சிறந்தோர், அழகிய பெயருடையோர், நம்பிக்கையுடையோர், உலகில் முதன்மையானோர், பலவிதமானோர் ஆகிய யாதுதானர்களை அவன் கண்டான்.',
        '0.15': 'தம் இயல்புக்கேற்ற பல குணங்கள் கொண்ட, ஒளிரும் அழகிய உருவினரைக் கண்டு அவன் மகிழ்ந்தான்; சில அருவருப்பானோரையும் கண்டான்.',
        '0.16': 'பின்னர் அங்கே அவர்களின் பெண்களைக் கண்டான் — சிறந்தோருக்குத் தகுந்தோர், தூய உள்ளத்தோர், பெருந்தன்மையோர், காதலரிடமும் மதுவிலும் ஈடுபாடுள்ளோர், விண்மீன்கள் போல் நல்லியல்புடையோர்.',
        '0.17': 'நாணத்தால் மூடியிருந்தும் ஒளிர்ந்த, நள்ளிரவில் காதலரால் அணைக்கப்பட்ட, பறவைகள் பறவைகளை அணைப்பது போல் சிலர் பெண்களால் அணைக்கப்பட்ட பெண்களை அவன் கண்டான்.',
        '0.18': 'வேறு சிலர் மாடிகளில் அமர்ந்து காதலர் மடியில் இன்பமாக இருந்தனர்; மற்றவர் கணவரிடம் பற்றும் தர்மத்தில் நிலையும் கொண்டு காதலில் மூழ்கியிருப்பதை அந்த அறிவாளி கண்டான்.',
        '0.19': 'சிலர் மேலாடையின்றிப் பொன் வரி நிறத்தினராக இருந்தனர்; சில சிறந்த பெண்கள் புடம்போட்ட பொன் நிறத்தினர்; வேறு சிலர் காதலரைப் பிரிந்து அழகிய அவயவங்கள் இருந்தும் நிலவு போல் வெளிறியிருந்தனர்.',
        '0.20': 'பின்னர் மனதுக்கினிய காதலரைப் பெற்று அன்பு நிறைந்து, மலர்ந்த மனத்துடன் இல்லங்களில் மகிழ்ந்திருந்த பேரழகிகளை அந்தக் கபிவீரன் கண்டான்.',
        '0.21': 'நிலவுபோல் ஒளிரும் முக வரிசைகளையும், வளைந்த அழகிய இமைகளுடைய நல்விழி வரிசைகளையும், மின்னல்களின் அழகிய மாலைகள் போன்ற அணிகலன் வரிசைகளையும் அவன் கண்டான்.',
        '0.22': 'ஆனால் மிக உயர்குடிப் பிறந்தவளும், நல்வழியில் நின்ற அரச குலத்தில் தோன்றியவளும், நன்கு வளர்ந்த மலர்ந்த கொடி போன்றவளும், மெல்லியவளும், மனத்தால் பிறந்தவள் போன்றவளுமான சீதையை அவன் காணவில்லை.',
        '0.23': 'நிலையான நெறியில் நின்றவள், ராமனையே நோக்குபவள், அவன் அன்பில் மூழ்கியவள், கணவனின் சீர்மிகு மனத்தில் புகுந்தவள், பிற எல்லாப் பெண்களினும் எப்போதும் சிறந்தவள்,',
        '0.24': 'துயர வெப்பத்தால் வாடியவள், கண்ணீரால் தொண்டை அடைத்தவள், முன்பு சிறந்த பொன்னாரம் அணிந்திருந்தவள், அழகிய இமைகளும் இனிய குரலும் கொண்டவள், காட்டில் ஆடும் மயில் போன்றவள்,',
        '0.25': 'தெளிவற்ற கோடுடைய பிறைநிலவு போலும், தூசு படிந்த பொன்வரி போலும், ஆறிய காயத்தின் தழும்பு போலும், காற்றால் வளைந்த மேகக்கோடு போலும் இருந்தவள் —',
        '0.26': 'மனிதர் தலைவனும் சொல்வன்மையில் சிறந்தவனுமான ராமனின் மனைவி சீதையைக் காணாமல் அந்தக் கபி நீண்ட நேரம் துயரால் வாடித் திடீரென்று சோர்ந்தவன் போல் ஆனான்.',
        '0.27': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் ஐந்தாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-06': {
      verses: {
        '0.0': 'விரும்பிய உருவெடுக்கும் அந்தக் கபி விமானம் போன்ற மாளிகைகளில் விருப்பம்போல் திரிந்து சுறுசுறுப்பாக இலங்கையில் உலவினான்.',
        '0.1': 'அந்த ஒளிமிக்கவன் சூரிய நிறமுடைய ஒளிரும் மதிலால் சூழப்பட்ட அரக்கர் அரசனின் மாளிகையை அடைந்தான்,',
        '0.2': 'சிங்கங்கள் பெருங்காட்டைக் காப்பது போல் கொடிய அரக்கர்கள் அதைக் காத்தனர். அந்த மாளிகையை நோக்கியபடி கபிசிரேஷ்டன் விளங்கினான்.',
        '0.3': 'வெள்ளி பதித்துப் பொன்னால் அலங்கரித்த விசித்திரத் தோரணங்களாலும், விசித்திர முற்றங்களாலும், அழகிய வாயில்களாலும் அது சூழப்பட்டிருந்தது,',
        '0.4': 'யானைகளின் மேல் அமர்ந்த வீரமிக்க களைப்பற்ற பாகர்களாலும், தடுக்க முடியாத தேர்க் குதிரைகளாலும் நிறைந்திருந்தது,',
        '0.5': 'சிங்க, புலித் தோல் உறைகள் கொண்ட, தந்தம், பொன், வெள்ளியால் அலங்கரிக்கப்பட்ட, முழங்கும் விசித்திரத் தேர்கள் அங்கு எப்போதும் சென்றன.',
        '0.6': 'பல ரத்தினங்கள் நிறைந்த, விலையுயர்ந்த இருக்கைகளால் அலங்கரிக்கப்பட்ட, மகாரதர்கள் கூடும், அவர்களுக்கான பெரும் ஆசனங்கள் கொண்ட இடம் அது.',
        '0.7': 'அழகிய, சிறந்த பலவித ஆயிரக்கணக்கான விலங்குகளாலும் பறவைகளாலும் அது சுற்றிலும் நிறைந்திருந்தது.',
        '0.8': 'ஒழுங்குடைய எல்லைக் காவலர்களாலும் அரக்கர்களாலும் நன்கு காக்கப்பட்டு, சிறந்த அழகிகளால் எங்கும் நிறைந்திருந்தது.',
        '0.9': 'மகிழ்ந்திருக்கும் பெண்மணிகளைக் கொண்ட அந்த அரக்கர் அரசனின் மாளிகை சிறந்த அணிகலன்களின் ஒலியால் கடல் முழக்கம் போல் ஒலித்தது.',
        '0.10': 'அரச இலக்கணங்கள் நிறைந்த, சிறந்த சந்தனம் மணக்கும், பெரியோர் நிறைந்த அது சிங்கங்கள் நிறைந்த பெருங்காடு போல் இருந்தது.',
        '0.11': 'பேரிகை, மிருதங்க ஒலியாலும் சங்கநாதத்தாலும் முழங்கும், நாள்தோறும் வழிபடப்படும், பருவ நாட்களில் ஹோமம் நடக்கும், அரக்கர்களால் எப்போதும் போற்றப்படும் இடம் அது.',
        '0.12': 'கடல் போல் ஆழமானதும் கடல் போல் முழங்குவதுமான அந்த மகானின் பெரும் மாளிகை பெரும் ரத்தினங்களால் ஆன பொருட்களைக் கொண்டிருந்தது.',
        '0.13': 'பெரும் ரத்தினங்கள் நிறைந்த, அழகால் ஒளிரும், யானைகள், குதிரைகள், தேர்கள் நெருங்கிய அதை அந்த மகாகபி கண்டான்.',
        '0.14': 'அதை இலங்கையின் அணிகலன் என்றே அந்த மகாகபி எண்ணினான். ஹனுமான் அங்கே ராவணனுக்கு அருகில் திரிந்தான்.',
        '0.15': 'அச்சமின்றி அவன் அரக்கர்களின் வீடு வீடாகச் சென்று, எல்லாத் தோட்டங்களையும் மாளிகைகளையும் பார்த்தபடி திரிந்தான்.',
        '0.16': 'பெரும் வேகமும் வீரமும் கொண்ட அவன் பிரஹஸ்தனின் வீட்டின் மேல் குதித்து, அங்கிருந்து மகாபார்ஸ்வனின் மற்றொரு வீட்டுக்குத் தாவினான்.',
        '0.17': 'பின்னர் அந்த மகாகபி மேகம் போன்ற கும்பகர்ணனின் வீட்டுக்கும், அவ்வாறே விபீஷணனின் வீட்டுக்கும் தாவினான்,',
        '0.18': 'மகோதரன், விரூபாக்ஷன் ஆகியோரின் வீடுகளுக்கும், வித்யுஜ்ஜிஹ்வன், வித்யுன்மாலி ஆகியோரின் மாளிகைகளுக்கும்,',
        '0.19': 'வஜ்ரதம்ஷ்ட்ரனின் வீட்டுக்கும் அந்த மகாகபி தாவினான்; பெரும் வேகமுடையவன் சுகன், அறிவாளி சாரணன் ஆகியோரின் வீடுகளுக்கும் தாவினான்.',
        '0.20': 'வானரப் படைத் தலைவன் இந்திரஜித்தின் வீட்டுக்குச் சென்றான்; அந்த ஹரிசத்தமன் ஜம்புமாலி, சுமாலி ஆகியோரின் வீடுகளுக்கும் சென்றான்.',
        '0.21': 'அந்த மகாகபி ரஸ்மிகேது, சூரியசத்ரு, வஜ்ரகாயன் ஆகியோரின் வீடுகளுக்குத் தாவினான்.',
        '0.22': 'பின்னர் வாயுபுத்திரன் தூம்ராக்ஷன், சம்பாதி, வித்யுத்ரூபன், பீமன், கனன், விகனன் ஆகியோரின் வீடுகளுக்குச் சென்றான்,',
        '0.23': 'சுகநாபன், சக்ரன், சடன், கபடன், ஹ்ரஸ்வகர்ணன், தம்ஷ்ட்ரன், அரக்கன் லோமசன் ஆகியோரின் வீடுகளுக்கும்,',
        '0.24': 'யுத்தோன்மத்தன், மத்தன், த்வஜக்ரீவன், சாதி, வித்யுஜ்ஜிஹ்வன், த்விஜிஹ்வன், ஹஸ்திமுகன் ஆகியோரின் வீடுகளுக்கும்,',
        '0.25': 'கராளன், பிசாசன், சோணிதாக்ஷன் ஆகியோரின் வீடுகளுக்கும் — இவ்வாறு வரிசையாகத் தாவியபடி வாயுபுத்திரன் ஹனுமான் சென்றான்.',
        '0.26': 'அந்த விலையுயர்ந்த மாளிகைகளில் பெரும் புகழ்கொண்ட அந்த மகாகபி அச்செல்வந்தர்களின் செல்வத்தைக் கண்டான்.',
        '0.27': 'அனைவரின் வீடுகளையும் சுற்றிக் கடந்து, அந்த ஒளிமிக்கவன் பின்னர் அரக்கர் அரசனின் மாளிகையை அடைந்தான்.',
        '0.28': 'அங்கே திரிந்த அந்தக் கபிசார்தூலன் ராவணனின் அருகில் உறங்கும் விகாரக் கண்களுடைய அரக்கியரைக் கண்டான்.',
        '0.29': 'அந்த அரக்கர் தலைவனின் இல்லத்தில் சூலம், சுத்தி, ஈட்டி, தோமரம் ஏந்திய பலவிதக் காவல் படைகளை அவன் கண்டான்,',
        '0.30': 'பலவித ஆயுதங்களை ஏந்திய பேருருவ அரக்கர்களையும், சிவப்பு, வெள்ளை, சாம்பல் நிறப் பெரும் வேகக் குதிரைகளையும்,',
        '0.31': 'உயர்குலமும் அழகும் கொண்ட, பகை யானைகளை நொறுக்கும், யானைப் பயிற்சியில் தேர்ந்த, போரில் ஐராவதத்திற்கு நிகரான யானைகளையும்,',
        '0.32': 'பகைப் படைகளை அழிக்கும் அவற்றை அந்த இல்லத்தில் கண்டான் — மழை பொழியும் மேகங்கள் போலும், நீர் சுரக்கும் மலைகள் போலும் (மதநீர் பெருக்கியபடி),',
        '0.33': 'இடிபோல் முழங்கும், போரில் பகைவரால் வெல்ல முடியாதவற்றை. அங்கே பொன்னால் அலங்கரிக்கப்பட்ட ஆயிரம் படைப்பிரிவுகளை,',
        '0.34': 'பொன் வலைகளால் முழுதும் மூடப்பட்ட, இளஞ்சூரியன் போல் ஒளிர்ந்த அவற்றை அரக்கர் அரசன் ராவணனின் மாளிகையில் கண்டான்.',
        '0.35': 'வாயுபுத்திரனான அந்தக் கபி பலவித வடிவப் பல்லக்குகளையும், விசித்திரக் கொடிவீடுகளையும், ஓவியக் கூடங்களையும் கண்டான்,',
        '0.36': 'பிற விளையாட்டு இல்லங்களையும், மரத்தாலான செயற்கைக் குன்றுகளையும், இனிய காம இல்லத்தையும், பகல் ஓய்வு இல்லத்தையும்,',
        '0.37': 'அரக்கர் அரசன் ராவணனின் மாளிகையில் கண்டான். மந்தர மலை போன்ற, மயில் தங்குமிடங்கள் நிறைந்த,',
        '0.38': 'கொடிக்கம்பங்கள் நிறைந்த அந்தச் சிறந்த மாளிகையைக் கண்டான் — சுற்றிலும் அளவற்ற ரத்தினக் குவியல்களும் நிதிகளும் கொண்ட, திறமையான சிற்பிகள் அமைத்த பகுதிகள் கொண்ட, பூதபதியின் (சிவனின்) இல்லம் போன்ற அதை.',
        '0.39': 'ரத்தினங்களின் ஒளியாலும் ராவணனின் தேஜஸாலும் அந்த மாளிகை கதிர்களுடைய சூரியன் போல் ஒளிர்ந்தது.',
        '0.40': 'அந்த வானரப் படைத் தலைவன் முழுதும் பொன்னாலான படுக்கைகளையும் இருக்கைகளையும் ஒளிரும் பாத்திரங்களையும் கண்டான்.',
        '0.41': 'தேனும் மதுவும் சிந்தி ஈரமான, மணிக் கிண்ணங்கள் நிறைந்த, மனதுக்கினிய விசாலமான அது குபேரனின் மாளிகை போல் இருந்தது,',
        '0.42': 'சிலம்புகளின் ஒலியாலும், ஒட்டியாணங்களின் ஓசையாலும், மிருதங்கம், கைத்தாளங்களின் முழக்கத்தாலும் ஒலித்தது.',
        '0.43': 'மாளிகைத் தொகுதிகள் கொண்ட, நூற்றுக்கணக்கான பெண்மணிகள் நிறைந்த, நன்கு அமைக்கப்பட்ட முற்றங்கள் கொண்ட அந்தப் பெரும் இல்லத்தில் ஹனுமான் நுழைந்தான்.',
        '0.44': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் ஆறாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-07': {
      verses: {
        '0.0': 'வைடூரியமும் பொன்னும் கலந்த சாளரங்கள் தொங்கும் மாளிகைத் தொகுதியை அந்த வலியவன் கண்டான் — மழைக்காலத்தில் மின்னல்களும் பறவைக் கூட்டங்களும் கொண்ட பெரும் மேகத் திரள் போல்.',
        '0.1': 'மாளிகைகளில் பலவிதக் கூடங்களை — சங்கு, ஆயுதம், வில் ஆகியவற்றுக்கான முதன்மைக் கூடங்களை — மலைபோன்ற வீடுகளின் மேல் மனதுக்கினிய விசாலமான நிலா மாடங்களையும் அவன் கண்டான்.',
        '0.2': 'பலவிதச் செல்வங்களால் ஒளிரும், தேவர்களாலும் அசுரர்களாலும் போற்றப்பட்ட, எல்லாக் குறைகளும் அற்ற, தன் வலிமையால் ஈட்டிய வீடுகளைக் கபி கண்டான்.',
        '0.3': 'மிகுந்த முயற்சியுடன் கட்டப்பட்ட, மயனே நேரில் படைத்தது போன்ற, பூமியில் எல்லா நலன்களிலும் சிறந்த இலங்கை வேந்தனின் வீடுகளை அவன் கண்டான்.',
        '0.4': 'பின்னர் உயர்ந்த மேகம் போன்ற, மனதுக்கினிய, அழகிய பொன் வடிவுடைய, அரக்கர் தலைவனின் வலிமைக்கேற்ற, ஒப்பற்ற வடிவுடைய சிறந்த இல்லத்தை அவன் கண்டான்.',
        '0.5': 'பூமியில் பரந்த சொர்க்கம் போன்று, அழகால் ஒளிரும், பல ரத்தினங்கள் நிறைந்த, பலவித மரங்களின் மலர்கள் மூடிய, மகரந்தம் படிந்த மலைமுடி போல் இருந்தது.',
        '0.6': 'சிறந்த பெண்களால் ஒளிர்வது போலும், மின்னல்களால் அலங்கரிக்கப்பட்ட மேகம் போலும், சிறந்த அன்னங்கள் சுமந்து செல்வது போலும், அழகுடன் வானில் நன்கு அமைக்கப்பட்ட விமானம் போல் இருந்தது.',
        '0.7': 'பல தாதுக்களால் சித்திரிக்கப்பட்ட மலைமுடி போலும், கோள்களாலும் சந்திரனாலும் சித்திரிக்கப்பட்ட வானம் போலும், அழகிய மேக ஓவியங்களாலும் பல ரத்தினங்களாலும் சித்திரிக்கப்பட்ட விமானத்தை அவன் கண்டான்.',
        '0.8': 'அதில் பூமி மலைத்தொடர்கள் நிறைந்ததாகவும், மலைகள் மரத்திரள்கள் நிறைந்தவையாகவும், மரங்கள் மலர்க்கொத்துகள் நிறைந்தவையாகவும், மலர்கள் மகரந்தமும் இதழ்களும் நிறைந்தவையாகவும் வடிக்கப்பட்டிருந்தன.',
        '0.9': 'அதில் வெண்மாளிகைகளும், மலர்ந்த தாமரைக் குளங்களும், மகரந்தமுடைய தாமரைகளும், விசித்திரக் காடுகளும் ஏரிகளும் வடிக்கப்பட்டிருந்தன.',
        '0.10': 'அங்கே புஷ்பகம் என்ற பெயருடைய, ஒளிரும், ரத்தின ஒளிகளால் மின்னும், சிறந்த மாளிகைகளினும் உயர்ந்த பெரும் விமானத்தை அந்த மகாகபி கண்டான்.',
        '0.11': 'அதில் வைடூரியப் பறவைகளும், வெள்ளி பவளப் பறவைகளும், பலவித ரத்தினங்களால் சித்திரிக்கப்பட்ட பாம்புகளும், இனத்திற்கேற்ற அழகிய அவயவங்களுடைய குதிரைகளும் வடிக்கப்பட்டிருந்தன.',
        '0.12': 'பவளமும் பொன்மலர்களும் கொண்ட சிறகுகள், விளையாட்டாக வளைந்த சிறகுகள், அழகிய முகம், அழகிய இறகுகள் கொண்ட பறவைகள் மன்மதனின் சிறகுகள் போலவே ஒளிர்ந்தன.',
        '0.13': 'அழகிய துதிக்கைகள் கொண்ட யானைகள் மகரந்தமுடைய தாமரை இலைகளை ஏந்தியிருந்தன; அழகிய கைகளுடைய தாமரை ஏந்திய லக்ஷ்மி தேவி தாமரைக் குளத்தில் இருப்பது போல் வடிக்கப்பட்டிருந்தாள்.',
        '0.14': 'அழகிய குகைகள் கொண்ட மலை போன்ற அந்த அழகிய இல்லத்தை அணுகி அவன் வியந்தான்; பனிக்காலம் முடிந்தபின் அழகிய குகைகள் கொண்ட மலை போல் அது மிக நறுமணமும் அழகும் கொண்டிருந்தது.',
        '0.15': 'பின்னர் பத்துத் தலையனின் கரங்களால் காக்கப்பட்ட அந்தப் போற்றப்பட்ட நகரில் திரிந்தும், போற்றத்தக்கவளும், மிகவும் துயருற்றவளும், கணவனின் நற்குணங்களின் ஈர்ப்பால் கட்டுண்டவளுமான ஜனகன் மகளைக் கபி காணவில்லை.',
        '0.16': 'அப்போது பலவாறு பண்பட்ட மனமுடைய, தன்னடக்கமுடைய, நல்வழி நடக்கும், கூர்ந்த பார்வையுடைய அந்த மகாத்மா ஜனகன் மகளைக் காணாமல் திரிந்தபோது அவன் மனம் மிகவும் வருந்தியது.',
        '0.17': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் ஏழாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-08': {
      verses: {
        '0.0': 'அந்த மாளிகையின் நடுவே நின்ற அறிவாளியான வாயுபுத்திரக் கபி மணிகளாலும் ரத்தினங்களாலும் சித்திரிக்கப்பட்ட, புடம்போட்ட பொன் சாளரங்களால் அமைக்கப்பட்ட பெரும் விமானத்தைக் கண்டான்.',
        '0.1': 'அளவற்ற நுட்பத்துடன், "நன்று" என்று விஸ்வகர்மாவே தானே அமைத்த அது, வானுக்கு எழும்போது காற்று வழியில் நிலைபெற்றுச் சூரிய வழியின் அடையாளம் போல் விளங்கியது.',
        '0.2': 'அங்கு முயற்சியுடன் செய்யப்படாதது எதுவும் இல்லை, விலையுயர்ந்த ரத்தினம் இல்லாதது எதுவும் இல்லை; அத்தகைய சிறப்புகள் தேவர்களிடமும் இல்லை; பெரும் சிறப்பு இல்லாதது அங்கு எதுவும் இல்லை.',
        '0.3': 'தவம், ஒருமுகம், வீரம் ஆகியவற்றால் ஈட்டப்பட்ட, மனம் நினைத்தபடி செல்லும், பல சிறப்பு அமைப்புகளால் கட்டப்பட்ட, எங்கும் சம சிறப்புடைய,',
        '0.4': 'மனத்தை ஒருமுகப்படுத்தினால் விரைந்து செல்லும், அணுகுவதற்கரிய, காற்றைப் போல் செல்லும், மகாத்மாக்கள், புண்ணியவான்கள், பெருஞ்செல்வர்கள், புகழ்மிக்கோர் ஆகியோரின் சிறந்த இன்ப உறைவிடம் போன்ற,',
        '0.5': 'சிறப்பான முறையில் சிறப்பாக அமைந்த, விசித்திரச் சிகரங்கள் கொண்ட, பல முகடுகளால் அலங்கரிக்கப்பட்ட, மனதுக்கினிய, கூதிர்கால நிலவு போல் தூய, விசித்திர முகடுகளுடைய மலைச்சிகரம் போன்ற,',
        '0.6': 'குண்டலங்களால் விளங்கும் முகங்களுடைய, பெருந்தீனியர்களான, வானில் திரியும், சுழலும் அகன்ற கண்களுடைய, பெரும் வேகமுடைய ஆயிரக்கணக்கான இரவுலாவிகளும் பூதகணங்களும் சுமக்கும்,',
        '0.7': 'வசந்தகால மலர்க்குவியல் போல் அழகாகத் தோன்றும், வசந்த மாதத்தைவிடவும் அழகிய அந்தச் சிறந்த புஷ்பக விமானத்தை அங்கே அந்த வானர வீரர்களில் சிறந்தவன் கண்டான்.',
        '0.8': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் எட்டாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-09': {
      verses: {
        '0.0': 'அந்தச் சிறந்த இருப்பிடத்தின் நடுவே வாயுபுத்திரன் ஹனுமான் தூய்மையான, விசாலமான சிறந்த மாளிகையைக் கண்டான்.',
        '0.1': 'அரை யோஜனை அகலமும் ஒரு யோஜனை நீளமும் கொண்ட அரக்கர் அரசனின் அந்தப் பெரும் மாளிகை பல அரண்மனைகளால் நிறைந்திருந்தது.',
        '0.2': 'நீண்ட விழிகளுடைய வைதேஹி சீதையைத் தேடியபடி பகைவனை அழிக்கும் ஹனுமான் எங்கும் சுற்றினான்.',
        '0.3': 'அரக்கர்களின் அந்தச் சிறந்த இருப்பிடத்தைப் பார்த்தபடி ஒளிமிக்க ஹனுமான் அரக்கர் அரசனின் இல்லத்தை அடைந்தான்,',
        '0.4': 'நான்கு தந்தங்களும் மூன்று தந்தங்களும் கொண்ட யானைகளால் சூழப்பட்ட, விசாலமான, ஆயுதம் ஏந்தியோரால் காக்கப்பட்ட இல்லத்தை.',
        '0.5': 'ராவணனின் இல்லம் அரக்கி மனைவியராலும், வலிமையால் கவர்ந்து வரப்பட்ட அரசகுமாரிகளாலும் நிறைந்திருந்தது.',
        '0.6': 'அது முதலைகளும் மகரங்களும் நிறைந்த, திமிங்கிலங்களும் மீன்களும் நிறைந்த, காற்று வேகத்தால் அலைக்கழிக்கப்படும், பாம்புகள் நிறைந்த கடல் போல் இருந்தது.',
        '0.7': 'வைஸ்ரவணனிடமும் (குபேரனிடமும்), சந்திரனிடமும், பச்சைக் குதிரைகளுடைய இந்திரனிடமும் உள்ள செல்வச் சிறப்பு ராவணனின் இல்லத்தில் எப்போதும் நிலையாக அழகுடன் இருந்தது.',
        '0.8': 'குபேர அரசன், யமன், வருணன் ஆகியோரின் செல்வம் இங்கே அரக்கனின் இல்லத்தில் அதே அளவோ அதைவிட அதிகமாகவோ இருந்தது.',
        '0.9': 'அந்த அரண்மனையின் நடுவே பல மாடங்கள் கொண்ட நன்கு கட்டப்பட்ட மற்றொரு அமைப்பை வாயுபுத்திரன் கண்டான்.',
        '0.10': 'அது பிரம்மனுக்காக விஸ்வகர்மா சொர்க்கத்தில் அமைத்த, எல்லா ரத்தினங்களாலும் அலங்கரிக்கப்பட்ட புஷ்பகம் என்ற தெய்வீக விமானம்.',
        '0.11': 'குபேரன் கடும் தவத்தால் பிதாமகனிடமிருந்து அதைப் பெற்றான்; அரக்கர் அரசன் வலிமையால் குபேரனை வென்று அதைப் பெற்றான்.',
        '0.12': 'ஓநாய் உருவங்கள் கொண்ட நன்கு அமைக்கப்பட்ட பொற்தூண்களால் அது நிறைந்திருந்தது; அழகால் ஒளிர்வது போல் இருந்தது.',
        '0.13': 'மேரு மந்தரம் போன்ற, வானைக் கீறுவது போன்ற முகட்டு மண்டபங்களாலும் அழகிய அறைகளாலும் அது எங்கும் அலங்கரிக்கப்பட்டிருந்தது.',
        '0.14': 'நெருப்பும் சூரியனும் போல் ஒளிரும் அதை விஸ்வகர்மா நன்கு அமைத்திருந்தான்; பொற்படிகளும் அழகிய சிறந்த மேடைகளும் அதில் இருந்தன,',
        '0.15': 'பொன்னாலும் பளிங்காலுமான சாளரங்களும், இந்திரநீலம் மகாநீலம் ஆகிய மணிகளின் சிறந்த மேடைகளும் அதில் இருந்தன.',
        '0.16': 'விசித்திரப் பவளங்களாலும், விலைமதிப்பற்ற மணிகளாலும், ஒப்பற்ற முத்துக்களாலும் அதன் தளம் ஒளிர்ந்தது.',
        '0.17': 'செஞ்சந்தனமும் பொன்போல் ஒளிரும் சந்தனமும் கொண்ட புனித நறுமணத்துடன் அது இளஞ்சூரியன் போல் இருந்தது.',
        '0.18': 'பலவித அழகிய வடிவ முகட்டு மண்டபங்களால் அலங்கரிக்கப்பட்ட அந்தத் தெய்வீகப் புஷ்பகத்தில் மகாகபி ஏறினான். அங்கு நின்று சுற்றிலும் பானம், தின்பண்டம், உணவு ஆகியவற்றின் மணத்தை,',
        '0.19': 'தெய்வீகமான எங்கும் பரவிய அதை உருவெடுத்த காற்றைப் போல் முகர்ந்தான். உறவினன் சிறந்த உறவினனை அழைப்பது போல் அந்த மணம் அந்த மகா வலிமையுடையவனிடம்,',
        '0.20': '"இங்கே வா" என்று ராவணன் இருந்த இடம் நோக்கி அழைப்பது போல் இருந்தது. அப்போது புறப்பட்ட அவன் ஒரு பெரிய மங்களகரமான மண்டபத்தைக் கண்டான்,',
        '0.21': 'ராவணனுக்கு மிகப் பிரியமான, சிறந்த பெண் போல் அழகிய, மணிப் படிகள் கொண்ட, பொன் சாளரங்களால் ஒளிரும்,',
        '0.22': 'பளிங்கால் பாவிய தளமுடைய, தந்தத்தில் பதித்த உருவங்கள் கொண்ட, முத்து, வைரம், பவளம், வெள்ளி, பொன் ஆகியவற்றால் ஆன,',
        '0.23': 'மணித்தூண்களால் அலங்கரிக்கப்பட்ட — சமமான, நேரான, மிக உயர்ந்த, எங்கும் அலங்கரிக்கப்பட்ட பல தூண்களால் விளங்கும்,',
        '0.24': 'சிறகுகள் போன்ற மிக உயர்ந்த தூண்களால் வானுக்குப் புறப்பட்டது போன்ற, பூமியின் அடையாளங்கள் கொண்ட பெரிய கம்பளம் விரிக்கப்பட்ட,',
        '0.25': 'பூமி போல் விரிந்த, நாடுகளும் வீடுகளும் சித்திரிக்கப்பட்ட, மதம்கொண்ட பறவைகளால் ஒலிக்கும், தெய்வீக மணம் கமழும்,',
        '0.26': 'விலையுயர்ந்த விரிப்புகள் கொண்ட, அரக்கர் தலைவன் வந்துபோகும், அகில் தூபப் புகை கமழும், தூய அன்னம் போல் வெண்மையான,',
        '0.27': 'இலை மலர் காணிக்கைகளால் பலவண்ணமாக ஒளிரும், மனதுக்கு மகிழ்ச்சி தரும், மேனி நிறத்திற்கும் பொலிவு தரும்,',
        '0.28': 'துயரை அழிக்கும், செல்வத்தையே பிறப்பிப்பது போன்ற அந்தத் தெய்வீக மண்டபம். ராவணனால் காக்கப்பட்ட அம்மண்டபம் ஐந்து சிறந்த புலன் பொருட்களால் ஐந்து புலன்களையும்,',
        '0.29': 'தாய் போல் மகிழ்வித்தது. "இது சொர்க்கமோ, தேவலோகமோ, இந்திரனின் நகரமோ, அல்லது பரம சித்தியோ" என்று மாருதி எண்ணினான்.',
        '0.30': 'அங்கே பெரும் சூதாடிகளிடம் சூதில் தோற்ற சூதாடிகள் போல் ஆழ்ந்த சிந்தனையில் இருப்பது போன்ற பொன் விளக்குகளை அவன் கண்டான்.',
        '0.31': 'விளக்குகளின் ஒளியாலும், ராவணனின் தேஜஸாலும், அணிகலன்களின் மினுமினுப்பாலும் அம்மண்டபம் சுடர்விடுகிறது என்று அவன் எண்ணினான்.',
        '0.32': 'பின்னர் கம்பளத்தில் அமர்ந்திருந்த, பலவண்ண ஆடைகளும் மாலைகளும் கொண்ட, பலவித வேடங்களில் அலங்கரித்த ஆயிரம் அழகிகளை அவன் கண்டான்.',
        '0.33': 'நள்ளிரவு கடந்திருந்தது; மதுவுக்கும் உறக்கத்துக்கும் வசப்பட்ட அவர்கள் இரவில் விளையாடி ஓய்ந்து அப்போது ஆழ்ந்து உறங்கினர்.',
        '0.34': 'அணிகலன்கள் ஒலியடங்கியிருந்த அந்த உறங்கும் கூட்டம் அன்னங்களும் வண்டுகளும் ஒலியடங்கிய பெரும் தாமரைக் காடு போல் விளங்கியது.',
        '0.35': 'பற்களை மூடிய, கண்களை மூடிய, தாமரை மணமுடைய அந்த அழகிகளின் முகங்களை மாருதி கண்டான்.',
        '0.36': 'பகலில் மலர்ந்த தாமரைகள் போன்ற அவர்களின் முகங்கள் அப்போது இரவில் இதழ்களை மூடிய தாமரைகள் போல் விளங்கின.',
        '0.37': '"மதம் கொண்ட வண்டுகள் மலர்ந்த தாமரைகளை நாடுவது போல் இந்த முகத்தாமரைகளை நிச்சயமாக மீண்டும் மீண்டும் நாடும்" —',
        '0.38': 'என்று அந்த ஒளிமிக்க மகாகபி காரணத்துடன் எண்ணினான்; குணங்களில் அவற்றை நீரில் பிறந்த தாமரைகளுக்கு நிகரானவை என்று கருதினான்.',
        '0.39': 'அப்பெண்களால் ஒளிர்ந்த அவனுடைய மண்டபம் விண்மீன்களால் அலங்கரிக்கப்பட்ட தெளிந்த கூதிர்கால வானம் போல் விளங்கியது.',
        '0.40': 'அவர்களால் சூழப்பட்ட அரக்கர் தலைவன் விண்மீன்களால் சூழப்பட்ட ஒளிமிக்க நட்சத்திர நாயகன் (சந்திரன்) போல் விளங்கினான்.',
        '0.41': '"எஞ்சிய புண்ணியம் தீர்ந்தபோது வானிலிருந்து விழும் விண்மீன்கள் அனைத்தும் இங்கே ஒன்றுகூடியுள்ளன" என்று அப்போது கபி எண்ணினான்.',
        '0.42': 'அங்கிருந்த பெண்களின் ஒளியும் நிறமும் பொலிவும் நல்லொளி கொண்ட பெரிய விண்மீன்கள் போல் தெளிவாக விளங்கின.',
        '0.43': 'அவர்களின் கூந்தல் கலைந்திருந்தது, கனத்த மாலைகளும் சிறந்த அணிகலன்களும் சிதறியிருந்தன; மது, விளையாட்டுக்குப் பின் அவர்களின் மனம் உறக்கத்தில் ஆழ்ந்திருந்தது.',
        '0.44': 'சிலரின் திலகங்கள் அழிந்திருந்தன, சிலரின் சிலம்புகள் நழுவியிருந்தன; சில அழகிகளின் ஆரங்கள் பக்கவாட்டில் நழுவியிருந்தன.',
        '0.45': 'வேறு சிலர் முத்தாரங்களால் சூழப்பட்டிருந்தனர், சிலரின் ஆடைகள் நெகிழ்ந்திருந்தன, ஒட்டியாணக் கயிறுகள் கோணியிருந்தன — ஓட்டிக் களைத்த இளம் பெண்குதிரைகள் போல்.',
        '0.46': 'வேறு சிலர் குண்டலங்கள் இன்றி, அறுந்து நசுங்கிய மாலைகளுடன், பெருங்காட்டில் யானையரசனால் மிதிக்கப்பட்ட பூத்த கொடிகள் போல் இருந்தனர்.',
        '0.47': 'சிலரின் மார்பகங்களுக்கு நடுவே நிலவுக்கதிர் போல் ஒளிரும் ஆரங்கள் உறங்கும் அன்னங்கள் போல் விளங்கின.',
        '0.48': 'மற்றவர்களின் வைடூரிய ஆரங்கள் காதம்பப் பறவைகள் போலவும், வேறு சிலரின் பொற்சங்கிலிகள் சக்கரவாகப் பறவைகள் போலவும் தோன்றின.',
        '0.49': 'அன்னங்கள், காரண்டவங்கள், சக்கரவாகங்களால் அழகுற்றது போல் அவர்கள் நதிகள் போலவும், அவர்களின் இடுப்புகள் மணல்திட்டுகள் போலவும் விளங்கின.',
        '0.50': 'சிறுமணி வரிசைகளே அலைகளாக, பொன் அணிகளே பெரும் தாமரைகளாக, உணர்ச்சிகளே முதலைகளாக, புகழே கரைகளாக — உறங்கிய அவர்கள் நதிகள் போல் விளங்கினர்.',
        '0.51': 'சிலரின் மென்மையான அவயவங்களிலும் மார்பு நுனிகளிலும் பதிந்த அணிகலன்களின் அழகிய தடங்கள் அணிகலன்கள் போலவே தோன்றின.',
        '0.52': 'சிலரின் மெல்லிய ஆடை முனைகள் முக மூச்சால் அசைந்து முகங்களின் மேல் மீண்டும் மீண்டும் படபடத்தன.',
        '0.53': 'பலவண்ண, பொன்னிற மனைவியரின் முகங்களருகே கொடிகள் போல் படபடத்த அழகிய ஒளியுடைய அந்த முனைகள் விளங்கின.',
        '0.54': 'நல்லொளியுடைய சில பெண்களின் குண்டலங்கள் முக மூச்சின் அசைவால் மெல்ல மெல்ல ஆடின.',
        '0.55': 'சர்க்கரை மதுவின் மணமுடைய, இயல்பாகவே நறுமணமும் இனிமையும் கொண்ட அவர்களின் மூச்சு அப்போது ராவணனை நோக்கி வீசியது.',
        '0.56': 'ராவணனின் சில மனைவியர் அதை ராவணனின் முகம் என்று எண்ணிச் சக்களத்திகளின் முகங்களை மீண்டும் மீண்டும் முகர்ந்தனர்.',
        '0.57': 'ராவணனிடம் மிகவும் பற்றுக்கொண்ட மனமுடைய அந்த அழகிகள் தன்வசமிழந்து அப்போது சக்களத்திகளிடமே அன்பு காட்டினர்.',
        '0.58': 'வேறு சில பெண்கள் காப்புகள் அணிந்த கைகளையும் அழகிய ஆடைகளையும் தலையணையாக்கி அங்கே உறங்கினர்.',
        '0.59': 'ஒருத்தி மற்றொருத்தியின் மார்பில், இன்னொருத்தி அவள் கையில்; ஒருத்தி மற்றொருத்தியின் மடியில், வேறொருத்தி அவள் மார்பகங்களில் சாய்ந்து உறங்கினர்.',
        '0.60': 'ஒருவரின் தொடை, விலா, இடுப்பு, முதுகு ஆகியவற்றை மற்றொருவர் சார்ந்து, ஒருவருக்கொருவர் அவயவங்களைப் பின்னிக்கொண்டு அவர்கள் போதைக்கும் அன்புக்கும் வசப்பட்டிருந்தனர்.',
        '0.61': 'ஒருவரின் அங்கத் தொடுகையால் மற்றொருவர் மகிழ்ந்தபடி அந்த மெல்லிடையாள்கள் அனைவரும் கைகளைப் பிணைத்து அங்கே உறங்கினர்.',
        '0.62': 'ஒருவரின் கைகள் என்ற நூலில் கோக்கப்பட்ட அந்தப் பெண் மாலை, நூலில் கோக்கப்பட்ட, மதம்கொண்ட வண்டுகள் கொண்ட மலர்மாலை போல் விளங்கியது.',
        '0.63': 'மாதவ மாதத்தில் (வசந்தத்தில்) மலர்ந்து, காற்று தீண்டி ஒன்றோடொன்று மாலை போல் பின்னிய, மலர்க்கொத்துகள் கலந்த கொடிகள் போல்,',
        '0.64': 'அழகிய அடிமரங்கள் பின்னிப் பிணைந்து, எங்கும் வண்டுகள் நிறைந்த, காற்றில் அசையும் காடு போல் ராவணனின் அந்தப் பெண்வனம் இருந்தது.',
        '0.65': 'எல்லாம் உரிய இடத்தில் இருந்தும் அப்போது அப்பெண்களின் அணிகள், அவயவங்கள், ஆடைகள், மாலைகள் இவற்றைத் தெளிவாகப் பிரித்தறிய முடியவில்லை.',
        '0.66': 'ராவணன் சுகமாக உறங்கும்போது, எரியும் பொன் விளக்குகள் பலவித ஒளியுடைய அப்பெண்களை இமைக்காமல் பார்ப்பது போல் இருந்தன.',
        '0.67': 'ராஜரிஷிகள், அந்தணர்கள், தைத்தியர்கள், கந்தர்வர்கள் ஆகியோரின் பெண்களும் அரக்கர்களின் கன்னியரும் அவன் காமத்துக்கு வசமாயினர்.',
        '0.68': 'இப்பெண்கள் அனைவரையும் போர் விரும்பும் ராவணன் கவர்ந்து வந்திருந்தான்; சிலர் மன்மதனால் மயங்கித் தாமாகவே வந்திருந்தனர்.',
        '0.69': 'அங்கிருந்த எந்தப் பெண்ணும் வலுக்கட்டாயமாகப் பெறப்பட்டவள் அல்ல; வீரத்துடன் கூடிய நற்குணத்தால் பெறப்பட்டவர்கள். சிறந்தவளான ஜனகன் மகளைத் தவிர எவரும் பிறரை விரும்பியவரோ முன்பு பிறருக்கு உரியவரோ அல்லர்.',
        '0.70': 'அவன் மனைவியரில் யாரும் தாழ்குலத்தவரோ அழகற்றவரோ, திறமையற்றவரோ நன்னடத்தை அறியாதவரோ, மனவலிமை குன்றியவரோ, கணவனுக்கு விருப்பமில்லாதவரோ இல்லை.',
        '0.71': 'நல்லறிவுடைய வானர அரசனுக்கு இவ்வாறு தோன்றியது: "பெரும் அரக்கர் அரசனின் இம்மனைவியர் அவனுடன் இருப்பது போல் ராகவனின் தர்மபத்தினியும் தன் கணவனுடன் இருந்தால் இவனுக்கு (ராவணனுக்கு) நன்மையாகும்."',
        '0.72': 'மீண்டும் தெளிந்து அவன் சிந்தித்தான்: "நிச்சயமாகச் சீதை குணங்களில் அனைவரினும் சிறந்தவள்; எனினும் இந்தப் பெரும் இலங்கை வேந்தன் அவள் விஷயத்தில் கொடிய இழிசெயலைச் செய்துள்ளான்."',
        '0.73': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் ஒன்பதாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-10': {
      verses: {
        '0.0': 'அங்கே பார்த்துக்கொண்டிருந்த ஹனுமான் தெய்வீகம் போன்ற, பளிங்கால் ஆன, ரத்தினங்களால் அலங்கரிக்கப்பட்ட முதன்மைப் படுக்கையைக் கண்டான்.',
        '0.1': 'தந்தம், பொன், வைடூரியம் பதித்த சிறந்த இருக்கைகளாலும் மிக விலையுயர்ந்த விரிப்புகளாலும் அது நிறைந்திருந்தது.',
        '0.2': 'அதன் ஒரு பகுதியில் தெய்வீக மாலைகளால் விளங்கும், நட்சத்திரத் தலைவன் (சந்திரன்) போன்ற வெண்குடையைக் கண்டான்.',
        '0.3': 'பொன் சூழ்ந்த, நெருப்புப் போல் ஒளிரும், அசோக மலர்மாலைகள் தொங்கும் சிறந்த ஆசனத்தைக் கண்டான்,',
        '0.4': 'சாமரம் ஏந்திய பெண்களால் சுற்றிலும் விசிறப்பட்ட, பலவித நறுமணங்கள் கமழும், சிறந்த தூபம் இடப்பட்ட,',
        '0.5': 'சிறந்த விரிப்புகள் விரித்த, செம்மறித் தோலால் மூடிய, சிறந்த மலர்ச் சரங்களால் சுற்றிலும் அழகுற்ற ஆசனத்தை.',
        '0.6': 'அதன் மேல் கார்மேகம் போன்ற, சுடரும் குண்டலங்கள் கொண்ட, சிவந்த கண்களுடைய, நீண்ட கரமுடைய, பொன்னாடை அணிந்தவன்,',
        '0.7': 'நறுமணச் செஞ்சந்தனம் பூசிய அவயவங்களுடைய, அந்தியால் சிவந்த மின்னலுடைய வான்மேகம் போன்றவன்,',
        '0.8': 'தெய்வீக அணிகலன்கள் பூண்ட, அழகிய, விரும்பிய உருவெடுக்கும், மரங்கள், காடுகள், புதர்களுடன் உறங்கும் மந்தர மலை போன்றவன்;',
        '0.9': 'இரவில் விளையாடி ஓய்வெடுத்த, சிறந்த அணிகலன்கள் பூண்ட, அரக்கக் கன்னியருக்குப் பிரியமான, அரக்கர்களுக்கு இன்பம் தருபவன்,',
        '0.10': 'மது அருந்தி ஓய்ந்திருந்த வீர அரக்கர் தலைவனை ஒளிரும் படுக்கையில் ஆழ்ந்து உறங்குவதை அந்த மகாகபி கண்டான்.',
        '0.11': 'யானை போல் மூச்சுவிட்ட ராவணனை அணுகி அந்த வானரோத்தமன் மிகவும் கலங்கி அஞ்சியவன் போல் பின்வாங்கினான்.',
        '0.12': 'பின்னர் படியேறி மற்றொரு மேடையைச் சார்ந்து அந்த மகாகபி போதையிலிருந்த அரக்கர்களின் புலியை நோக்கினான்.',
        '0.13': 'உறங்கும் அரக்கர் அரசனின் அழகிய படுக்கை மதயானை படுத்திருக்கும் பெரிய மலை ஊற்று போல் விளங்கியது.',
        '0.14': 'அந்தப் பெரும் அரக்கர் அரசனின் பொன் தோள்வளைகள் அணிந்த, நீட்டிய, இந்திரக் கொடிகள் போன்ற கைகளை அவன் கண்டான்;',
        '0.15': 'ஐராவதத்தின் தந்த நுனிகளின் அழுத்தத்தால் காயம்பட்ட, வஜ்ரத்தால் கீறப்பட்ட பருத்த தோள்கள் கொண்ட, விஷ்ணு சக்கரத்தால் காயமுற்ற கைகள்,',
        '0.16': 'பருத்த, சமமாக அழகாக அமைந்த தோள்களுடைய, உறுதியான, வலிமையான, நல்லிலக்கண நகங்களும் கட்டைவிரல்களும் கொண்ட, அழகிய மோதிரங்களால் குறிக்கப்பட்ட,',
        '0.17': 'இறுகிய, உலக்கைத் தடி வடிவுடைய, யானைத் துதிக்கை போல் உருண்ட, வெண் படுக்கையில் நீட்டிய ஐந்து தலை நாகங்கள் இரண்டு போன்ற,',
        '0.18': 'முயல் இரத்தம் போல் சிவந்த, மிகக் குளிர்ந்த, நறுமணமுள்ள விலையுயர்ந்த சந்தனம் நன்கு பூசி அலங்கரிக்கப்பட்ட,',
        '0.19': 'சிறந்த பெண்களால் வருடப்பட்ட, சிறந்த மணங்கள் கமழும், யக்ஷர், நாகர், கந்தர்வர், தேவர், தானவர்களை அலறச் செய்த கைகளை —',
        '0.20': 'படுக்கையில் வைத்திருந்த அவன் கைகளை மந்தர மலைப் பிளவில் உறங்கும் சினம்கொண்ட இரு பெரும் பாம்புகள் போல் அந்தக் கபி கண்டான்.',
        '0.21': 'நிறைவான அவ்விரு கைகளால் மலை போன்ற அரக்கர் அரசன் இரு சிகரங்கள் கொண்ட மந்தரம் போல் விளங்கினான்.',
        '0.22': 'மா, புன்னை மணமுடைய, சிறந்த மகிழம்பூ மணம் கலந்த, சுவையான உணவுச் சாரத்துடன் கூடிய, மதுவின் மணம் முன்னிற்கும்,',
        '0.23': 'உறங்கும் அந்த அரக்கர் அரசனின் மூச்சு அவனுடைய பெரிய வாயிலிருந்து வெளிவந்து அந்த இல்லம் முழுவதையும் நிரப்புவது போல் இருந்தது.',
        '0.24': 'முத்துக்களும் மணிகளும் பதித்த, சற்றே நழுவிய பொன் மகுடத்தால் அவன் விளங்கினான்; அவன் முகம் குண்டலங்களால் ஒளிர்ந்தது;',
        '0.25': 'செஞ்சந்தனம் பூசிய, ஒளிரும் ஆரம் அணிந்த, பருத்த, நீண்ட, அகன்ற மார்பால் அவன் விளங்கினான்;',
        '0.26': 'சிவந்த கண்களுடைய அவன் நெகிழ்ந்த வெண் பட்டாடையையும் விலையுயர்ந்த மஞ்சள் மேலாடையையும் நன்கு போர்த்தியிருந்தான்.',
        '0.27': 'உளுந்துக் குவியல் போல் கருத்த, பாம்பு போல் சீறும் அவன் கங்கையின் ஆழ்நீரில் உறங்கும் யானை போல் இருந்தான்.',
        '0.28': 'நான்கு பொன் விளக்குகளால் நான்கு திசைகளிலும் ஒளிர்ந்து, எல்லா அவயவங்களும் ஒளியூட்டப்பட்ட அவன் மின்னல்களால் ஒளிரும் மேகம் போல் இருந்தான்.',
        '0.29': 'மனைவியரிடம் அன்புள்ள அந்தப் பெரும் அரக்கர் தலைவனின் இல்லத்தில் அவன் பாதங்களருகே கிடந்த மனைவியரையும் அவன் கண்டான்.',
        '0.30': 'நிலவு போல் ஒளிரும் முகங்களுடைய, சிறந்த குண்டலங்கள் அணிந்த, வாடாத மாலைகளும் அணிகளும் கொண்ட அவர்களை அந்த வானரத் தலைவன் கண்டான்.',
        '0.31': 'நடனத்திலும் இசைக்கருவிகளிலும் தேர்ந்த, அரக்கர் அரசனின் கைகளிலும் மடியிலும் இருந்த, சிறந்த அணிகலன்கள் பூண்ட அவர்கள் அமர்ந்திருப்பதைக் கபி கண்டான்.',
        '0.32': 'அப்பெண்களின் காதுகளில் வைரமும் வைடூரியமும் பதித்த பொற்குண்டலங்களையும் தோள்வளைகளையும் அவன் கண்டான்.',
        '0.33': 'நிலவு போன்ற அவர்களின் முகங்களாலும் அழகாக ஆடும் குண்டலங்களாலும் அந்த விமானம் விண்மீன் கூட்டங்கள் நிறைந்த வானம் போல் விளங்கியது.',
        '0.34': 'போதையாலும் உழைப்பாலும் களைத்த அரக்கர் அரசனின் அந்த மெல்லிடைப் பெண்கள் ஆங்காங்கே கிடைத்த இடங்களில் உறங்கினர்.',
        '0.35': 'வேறொரு அழகிய நடனமாது மென்மையான நடன நிலைகளில் தன் அழகிய அவயவங்களை வைத்தபடி உறங்கினாள்.',
        '0.36': 'ஒருத்தி வீணையைத் தழுவியபடி உறங்கி, பெருநதியில் அடித்து வரப்பட்டுப் படகைப் பற்றிய தாமரைக்கொடி போல் விளங்கினாள்.',
        '0.37': 'கருவிழிகள் கொண்ட வேறொரு அழகி அக்குளில் மட்டுக வாத்தியத்தை வைத்தபடி உறங்கி, கைக்குழந்தையுடைய அன்புத் தாய் போல் தோன்றினாள்.',
        '0.38': 'எல்லா அவயவங்களும் அழகுடைய ஒருத்தி பறையைத் தன்மேல் வைத்தபடி, நீண்ட நாளுக்குப் பின் கிடைத்த காதலனைத் தழுவிய காதலி போல் உறங்கினாள்.',
        '0.39': 'தாமரைக் கண்ணுடைய ஒருத்தி வீணையைத் தழுவியபடி, தன் அன்புக் காதலனைப் பற்றிய காதலி போல் உறங்கினாள்.',
        '0.40': 'ஒழுங்குடைய நடனத்தில் தேர்ந்த வேறொருத்தி விபஞ்சி வீணையைப் பற்றியபடி காதலனுடன் இருக்கும் அழகி போல் உறக்கத்தில் ஆழ்ந்தாள்.',
        '0.41': 'போதைக் கண்களுடைய வேறொருத்தி பொன் போன்ற மென்மையான, திரண்ட, அழகிய அவயவங்களால் மிருதங்கத்தை அழுத்தியபடி உறங்கினாள்.',
        '0.42': 'மெல்லிய வயிறுடைய, குற்றமற்ற ஒருத்தி போதையால் களைத்து கைகளுக்கிடையே அக்குளில் இருந்த பணவ வாத்தியத்துடன் உறங்கினாள்.',
        '0.43': 'வேறொருத்தி டிண்டிமத்தைப் பற்றி அதனோடு ஒட்டியபடி, இளங்குழந்தையைத் தழுவிய அழகி போல் உறங்கினாள்.',
        '0.44': 'தாமரை இதழ் போன்ற கண்களுடைய ஒருத்தி போதையில் மயங்கி ஆடம்பர வாத்தியத்தைக் கைகளின் அணைப்பில் அழுத்தியபடி உறங்கினாள்.',
        '0.45': 'வேறொரு அழகி குடத்தைப் பக்கத்தில் தள்ளிவிட்டு உறங்கி, வசந்தத்தில் நீர் தெளிக்கப்பட்ட பலவண்ண மலர்மாலை போல் விளங்கினாள்.',
        '0.46': 'உறக்கத்தின் வலிமைக்குத் தோற்ற ஓர் இளம்பெண் பொற்கலசங்கள் போன்ற மார்பகங்களைக் கைகளால் அணைத்தபடி உறங்கினாள்.',
        '0.47': 'தாமரைக் கண்களும் முழுநிலவு முகமும் கொண்ட வேறொருத்தி போதையில் தளர்ந்து அழகிய இடையுடைய மற்றொருத்தியைத் தழுவியபடி உறங்கினாள்.',
        '0.48': 'சிறந்த பெண்கள் விசித்திர இசைக்கருவிகளைத் தழுவி, காதலியர் காதலரை அணைப்பது போல் மார்போடு அழுத்தியபடி உறங்கினர்.',
        '0.49': 'பின்னர் அவர்களிடமிருந்து தனியே வைக்கப்பட்ட அழகிய படுக்கையில் உறங்கிய அழகு நிறைந்த ஒரு பெண்ணை அந்தக் கபி கண்டான்,',
        '0.50': 'முத்துக்களும் மணிகளும் பதித்த அணிகலன்களால் நன்கு அலங்கரிக்கப்பட்ட, தன் பொலிவால் அந்தச் சிறந்த மாளிகையையே அலங்கரிப்பது போன்ற —',
        '0.51': 'வெண்ணிறமும் பொன்னொளியும் கொண்ட, அன்புக்குரிய, அந்தப்புரத்தின் தலைவியான, அழகிய வடிவுடைய மண்டோதரி அங்கு உறங்குவதைக் கபி கண்டான்.',
        '0.52': 'அவ்வாறு அலங்கரித்திருந்த அவளைக் கண்டு நீண்ட கரமுடைய வாயுபுத்திரன் அழகும் இளமையும் கண்டு "இவளே சீதை" என்று ஊகித்தான்; பெருமகிழ்ச்சியடைந்து அந்த வானரத் தலைவன் களிப்புற்றான்.',
        '0.53': 'தோள்களைத் தட்டினான், வாலை முத்தமிட்டான், மகிழ்ந்தான், விளையாடினான், பாடினான், அங்குமிங்கும் ஓடினான், தூண்களில் ஏறித் தரையில் குதித்தான் — குரங்குகளின் இயல்பைக் காட்டியபடி.',
        '0.54': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் பத்தாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-11': {
      verses: {
        '0.0': 'பின்னர் அந்த மகாகபி அந்த எண்ணத்தை உதறிவிட்டு நிலைகொண்டான்; சீதையைப் பற்றி வேறொரு சிந்தனையில் ஆழ்ந்தான்:',
        '0.1': '"ராமனைப் பிரிந்த அந்த உத்தமி உறங்கமாட்டாள், உண்ணமாட்டாள், அலங்கரித்துக் கொள்ளமாட்டாள், மது அருந்தமாட்டாள்;',
        '0.2': 'தேவர்களின் தலைவனாயினும் வேறொரு ஆடவனிடம் செல்லமாட்டாள்; தேவர்களிலும் ராமனுக்கு நிகரானவர் எவரும் இல்லை."',
        '0.3': '"இவள் வேறொருத்தி" என்று முடிவு செய்து சீதையைக் காணும் ஆவலுடன் அந்தக் கபிசிரேஷ்டன் மீண்டும் மதுக்கூடத்தில் திரிந்தான்.',
        '0.4': 'சிலர் விளையாட்டால் களைத்திருந்தனர், சிலர் பாட்டால், சிலர் நடனத்தால் களைத்திருந்தனர், வேறு சிலர் மதுவால் தன்னிலை மறந்திருந்தனர்.',
        '0.5': 'சிலர் முரசம், மிருதங்கம், சேலிகை மேல் சாய்ந்திருந்தனர்; வேறு சில பெண்கள் சிறந்த விரிப்புகளில் படுத்திருந்தனர்.',
        '0.6': 'அணிகலன்கள் பூண்ட, அழகு பற்றி உரையாடும் இயல்புடைய, தகுந்த பாடல்களின் பொருளைப் பேசும் ஆயிரம் பெண்களால்,',
        '0.7': 'இடத்துக்கும் காலத்துக்கும் ஏற்ப நடப்பவர், தகுந்த சொற்கள் பேசுபவர், காதலில் ஈடுபட்டவர் ஆகியோரால் அம்மண்டபம் நிறைந்திருப்பதை வானரத் தலைவன் கண்டான்.',
        '0.8': 'வேறிடத்திலும் அழகு பற்றிப் பேசியபடி படுத்த ஆயிரம் சிறந்த இளம்பெண்கள் உறங்குவதை அவன் கண்டான்.',
        '0.9': 'இடம் காலத்துக்கு ஏற்ற, தகுந்த சொற்கள் பேசும் அந்தக் கூட்டம் காதலிலிருந்து ஓய்ந்து உறங்குவதை வானரத் தலைவன் கண்டான்.',
        '0.10': 'அவர்கள் நடுவே நீண்ட கரமுடைய அரக்கர் அரசன் பெரிய கொட்டிலில் சிறந்த பசுக்களின் நடுவே காளை போல் விளங்கினான்.',
        '0.11': 'அவர்களால் சூழப்பட்ட அந்த அரக்கர் அரசன் காட்டில் பெண்யானைகளால் சூழப்பட்ட பெரும் யானை போல் விளங்கினான்.',
        '0.12': 'அந்தப் பெரும் அரக்கர் தலைவனின் இல்லத்தில் எல்லா விருப்பப் பொருட்களும் நிறைந்த மதுக்கூடத்தை அந்தக் கபிசார்தூலன் கண்டான்.',
        '0.13': 'அந்த மதுக்கூடத்தில் மான், எருமை, பன்றி இறைச்சிகள் பகுதி பகுதியாக வைக்கப்பட்டிருப்பதை அவன் கண்டான்.',
        '0.14': 'பெரிய பொற்பாத்திரங்களில் உண்ணாமல் விடப்பட்ட மயில்களையும் கோழிகளையும் அந்தக் கபிசார்தூலன் கண்டான்.',
        '0.15': 'தயிரும் சௌவர்ச்சல உப்பும் சேர்த்துச் சமைத்த பன்றி, வாத்ரீணச இறைச்சியையும், முள்ளம்பன்றி, மான், மயில்களையும் ஹனுமான் கண்டான்.',
        '0.16': 'கௌதாரிகளும், பலவித ஆடுகளும், பாதி உண்ட முயல்களும், எருமைகளும், ஏகசல்ய மீன்களும், நன்கு சமைத்த செம்மறிக்கடாக்களும் இருந்தன,',
        '0.17': 'பலவித நக்கும் பண்டங்களும் பானங்களும் உணவுகளும், புளிப்பும் உப்பும் கலந்த பலவித ராககாண்டவங்களும் இருந்தன,',
        '0.18': 'தூக்கி எறியப்பட்ட விலையுயர்ந்த பெரும் சிலம்புகளும் தோள்வளைகளும், மதுக் கிண்ணங்களிடையே சிதறிய பலவிதப் பழங்களும் இருந்தன.',
        '0.19': 'மலர்க் காணிக்கைகளுடைய தரை ஆங்காங்கே வைக்கப்பட்ட நன்கு அமைந்த படுக்கைகளாலும் இருக்கைகளாலும் மிகுந்த அழகு பெற்றது.',
        '0.20': 'நெருப்பின்றியே மதுக்கூடம் சுடர்விடுவது போல் தோன்றியது. சிறந்த பக்குவத்தில் தயாரிக்கப்பட்ட பலவிதமான,',
        '0.21': 'திறமையுடன் சமைத்து மதுக்கூடத்தில் தனித்தனியாக வைக்கப்பட்ட இறைச்சிகளுடன், தெய்வீகமான தெளிந்த பலவித சுராபானங்களும் வடித்த மதுக்களும்,',
        '0.22': 'சர்க்கரை மது, தேன் மது, மலர் மது, பழ மது ஆகியவை பலவித நறுமணப் பொடிகளால் தனித்தனியாக மணமூட்டப்பட்டிருந்தன.',
        '0.23': 'பல இடங்களில் வைக்கப்பட்ட மாலைகளால் மூடப்பட்ட, பொற்கலசங்களும் பளிங்குப் பாத்திரங்களும் கொண்ட தரை விளங்கியது,',
        '0.24': 'வேறு பொற்கமண்டலங்களாலும் சூழப்பட்டிருந்தது; வெள்ளி, பொற்குடங்களில் —',
        '0.25': 'அத்தகைய சிறந்த மதுக்கூடத்தை அங்கே கபி கண்டான். சீது (மது) நிறைந்த பொன்னாலும் மணிகளாலுமான பாத்திரங்களை அவன் கண்டான்.',
        '0.26': 'அந்த மகாகபி அப்பாத்திரங்களைக் கண்டான் — சில நிறைந்தவை, சில பாதி மீதமுள்ளவை, சில முழுதும் குடிக்கப்பட்டவை;',
        '0.27': 'சில இடங்களில் தொடப்படாத பானங்களைக் கண்டான்; சில இடங்களில் பலவித உணவுகளையும், சில இடங்களில் பகுதி பகுதியாக வைக்கப்பட்ட பானங்களையும்;',
        '0.28': 'சில இடங்களில் பாதி மீதமுள்ளவற்றைப் பார்த்தபடி அவன் திரிந்தான். அங்கே பெண்களின் பல படுக்கைகள் காலியாக இருந்தன; சில அழகிகள் ஒருவரையொருவர் தழுவியபடி உறங்கினர்.',
        '0.29': 'உறக்கத்தின் வலிமைக்குத் தோற்ற ஒருத்தி மற்றொருத்தியின் ஆடையை இழுத்துப் போர்த்திக்கொண்டு அவளருகே சென்று உறங்கினாள்.',
        '0.30': 'அவர்களின் மூச்சுக் காற்றால் அவர்கள் உடலின் மேலிருந்த பலவண்ண ஆடைகளும் மாலைகளும் மெல்லிய தென்றல் தீண்டியது போல் சற்றே அசைந்தன.',
        '0.31': 'குளிர்ந்த சந்தனம், இனிய சுவையுடைய மது, பலவித மாலைகள், பலவித மலர்கள் ஆகியவற்றின்,',
        '0.32': 'நீராடல், சந்தனப் பூச்சு, தூபம் ஆகியவற்றின் பலவித மணத்தைக் கலந்து காற்று பலவாறு சுமந்தபடி,',
        '0.33': 'அப்போது புஷ்பக விமானத்தில் இனிய நறுமணம் வீசியது. அங்கே சில அழகிகள் கருமையும் வெண்மையும் கலந்தவர், சிலர் கருநிறத்தவர்,',
        '0.34': 'அரக்கனின் இல்லத்தில் சில பெண்கள் பொன்னிற அவயவங்கள் உடையவர். உறக்கத்துக்கு வசப்பட்டதாலும் காமத்தால் மயங்கியதாலும்,',
        '0.35': 'அவர்களின் அழகு இரவில் கூம்பிய தாமரைக்கொடிகள் போல் இருந்தது. இவ்வாறு பேரொளி கொண்ட அந்தக் கபி ராவணனின் அந்தப்புரம் முழுவதையும் கண்டான்; ஆனால் ஜானகியைக் காணவில்லை.',
        '0.36': 'அப்பெண்களைப் பார்த்துக்கொண்டிருந்த அந்த மகாகபி தர்மம் பற்றிய அச்சத்தால் பெரும் ஐயத்தில் ஆழ்ந்தான்.',
        '0.37': '"உறங்கும் பிறர் மனைவியரின் அந்தப்புரத்தைப் பார்ப்பது — இது நிச்சயமாக என் தர்மத்திற்குப் பெரும் இழுக்கை உண்டாக்கும்.',
        '0.38': 'என் பார்வை ஒருபோதும் பிறர் மனைவியர் பக்கம் சென்றதில்லை; ஆனால் இங்கே நான் பிறர் மனைவியரை, அவன் அந்தப்புரப் பெண்களைக் கண்டுவிட்டேன்."',
        '0.39': 'அப்போது ஒருமுகமாக உறுதியான மனமுடைய அந்த மனவலியவனுக்குக் காரியத்தின் சரியான வழியைக் காட்டும் மற்றொரு எண்ணம் தோன்றியது:',
        '0.40': '"உண்மைதான், கவலையின்றி உறங்கிய ராவணனின் எல்லாப் பெண்களையும் நான் பார்த்தேன்; ஆனால் என் மனத்தில் சிறிதும் சலனம் எழவில்லை.',
        '0.41': 'நல்ல தீய நிலைகளில் எல்லாப் புலன்களையும் இயக்குவது மனமே; என் அந்த மனம் நன்கு நிலைபெற்றுள்ளது.',
        '0.42': 'வைதேஹியை வேறெங்கும் என்னால் தேட முடியாது; தேடும்போது பெண்கள் எப்போதும் பெண்களிடையேதான் காணப்படுவர்.',
        '0.43': 'எந்த உயிரின் இனம் எதுவோ அதிலேயே அதைத் தேடுவர்; காணாமல் போன பெண்ணைப் பெண்மான்களிடையே தேட முடியாது.',
        '0.44': 'ஆகவே தூய மனத்துடன் ராவணனின் இந்த அந்தப்புரம் முழுவதையும் நான் தேடினேன்; எனினும் ஜானகி காணப்படவில்லை."',
        '0.45': 'தேவ கந்தர்வ கன்னியரையும் நாக கன்னியரையும் பார்த்தும் வீரன் ஹனுமான் ஜானகியைக் காணவில்லை.',
        '0.46': 'பிற அழகிகளைக் கண்டும் அங்கே அவளைக் காணாமல் அந்த வீரக் கபி அங்கிருந்து விலகி வேறிடம் செல்ல முற்பட்டான்.',
        '0.47': 'பின்னர் ஒளிமிக்க மாருதி மீண்டும் முயற்சியை மேற்கொண்டு மதுக்கூடத்தை விட்டு எங்கும் அவளைத் தேடத் தொடங்கினான்.',
        '0.48': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் பதினொன்றாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
  },
};
